// ---- EMPRESAS (cadastro; OS só para placas de empresa cadastrada) ----
function getEmpresas(){
  if(!D.config.empresas)D.config.empresas=[];
  return D.config.empresas;
}
function popEmpresas(){
  // Popula selects de empresa (veículo)
  const sel=document.getElementById('eq-empresa');
  if(sel){
    const atual=sel.value;
    sel.innerHTML='<option value="">Selecionar...</option>';
    getEmpresas().forEach(e=>{sel.innerHTML+=`<option value="${e.nome}">${e.nome}</option>`;});
    if(atual)sel.value=atual;
  }
}
function novaEmpresa(){
  const nome=prompt('Nome da empresa:');
  if(!nome||!nome.trim())return;
  const n=nome.trim();
  const lista=getEmpresas();
  if(lista.some(e=>e.nome.toLowerCase()===n.toLowerCase())){toast('Empresa já cadastrada','er');return;}
  const cnpj=prompt('CNPJ da empresa (opcional):')||'';
  lista.push({id:uid(),nome:n,cnpj:cnpj.trim()});
  // Se é a 1ª empresa, oferece atribuir todos os veículos sem empresa a ela
  const semEmpresa=D.equips.filter(e=>!e.empresa);
  if(lista.length===1 && semEmpresa.length>0){
    if(confirm('Deseja atribuir os '+semEmpresa.length+' veículos atuais à empresa "'+n+'"?\n\n(Necessário para poder gerar OS para eles.)')){
      semEmpresa.forEach(e=>{e.empresa=n;});
      toast(semEmpresa.length+' veículos atribuídos a '+n,'ok');
    }
  }
  sv();
  if(document.getElementById('eq-empresa')){popEmpresas();document.getElementById('eq-empresa').value=n;}
  if(typeof rdEmpresas==='function')rdEmpresas();
  toast('Empresa "'+n+'" cadastrada!','ok');
}
function delEmpresa(id){
  reqSenha(()=>{
    const e=getEmpresas().find(x=>x.id===id);
    if(!e)return;
    if(!confirm('Excluir a empresa "'+e.nome+'"?\n\nOs veículos dela ficarão sem empresa (não poderão gerar OS até serem reatribuídos).'))return;
    D.config.empresas=getEmpresas().filter(x=>x.id!==id);
    if(typeof auditarExclusao==='function')auditarExclusao('empresas','Excluiu empresa: '+(e.nome||id));
    sv();if(typeof rdEmpresas==='function')rdEmpresas();
    toast('Empresa excluída','ok');
  });
}

function toggleEmpresasPanel(){
  const p=document.getElementById('empresas-panel');
  if(!p)return;
  p.style.display=p.style.display==='none'?'':'none';
  if(p.style.display!=='none')rdEmpresas();
}
function rdEmpresas(){
  const el=document.getElementById('empresas-lista');
  if(!el)return;
  const lista=getEmpresas();
  if(!lista.length){el.innerHTML='<p class="empty" style="padding:8px">Nenhuma empresa cadastrada. Cadastre ao menos uma para poder gerar OS.</p>';return;}
  el.innerHTML='<div class="tw"><table><thead><tr><th>Empresa</th><th>CNPJ</th><th>Veículos</th><th></th></tr></thead><tbody>'+
    lista.map(e=>{
      const qtd=D.equips.filter(v=>v.empresa===e.nome).length;
      return `<tr><td><b>${e.nome}</b></td><td style="font-size:11px">${e.cnpj||'-'}</td><td>${qtd}</td>
      <td><button class="btn bd btn-xs" onclick="delEmpresa('${e.id}')" title="Excluir">×</button></td></tr>`;
    }).join('')+'</tbody></table></div>';
}

// ---- RESPONSÁVEIS DE OS (cadastrável) ----
function getResponsaveis(){
  if(!D.config.responsaveis)D.config.responsaveis=[];
  if(!D.config.responsaveis)D.config.responsaveis=[];
  if(!D.config.empresas)D.config.empresas=[];
  return D.config.responsaveis;
}
function popResponsaveis(){
  const sel=document.getElementById('mn-re');
  if(!sel)return;
  const atual=sel.value;
  sel.innerHTML='<option value="">Selecionar...</option>';
  getResponsaveis().forEach(r=>{sel.innerHTML+=`<option value="${r}">${r}</option>`;});
  sel.innerHTML+='<option value="__manual__">✏️ Digitar manual...</option>';
  if(atual)sel.value=atual;
}
function novoResponsavel(){
  const nome=prompt('Nome do novo responsável:');
  if(!nome||!nome.trim())return;
  const n=nome.trim();
  const lista=getResponsaveis();
  if(lista.some(r=>r.toLowerCase()===n.toLowerCase())){toast('Responsável já cadastrado','er');return;}
  lista.push(n);
  sv();popResponsaveis();
  document.getElementById('mn-re').value=n;
  toggleRespManual();
  toast('Responsável "'+n+'" cadastrado!','ok');
}
function toggleRespManual(){
  const sel=document.getElementById('mn-re');
  const man=document.getElementById('mn-re-manual');
  if(!sel||!man)return;
  if(sel.value==='__manual__'){man.style.display='';man.focus();}
  else{man.style.display='none';man.value='';}
}

function popSels(){
  if(typeof popResponsaveis==='function')popResponsaveis();
  if(typeof popEmpresas==='function')popEmpresas();
  const empresasCad=getEmpresas().map(e=>e.nome);
  // mn-eq: SÓ veículos de empresa cadastrada (regra da OS). ct-eq: todos disponíveis.
  ['mn-eq','ct-eq'].forEach(id=>{const el=document.getElementById(id);if(!el)return;el.innerHTML='<option value="">Selecionar...</option>';let lista=D.equips.filter(e=>e.st!=='vendido'&&e.st!=='imobilizado');if(id==='mn-eq')lista=lista.filter(e=>e.empresa&&empresasCad.includes(e.empresa));lista.forEach(e=>{el.innerHTML+=`<option value="${e.id}">${e.placa} — ${e.mk} ${e.mo}${e.empresa?' ['+e.empresa+']':''}</option>`;});});
  const mct=document.getElementById('med-ct');if(mct){mct.innerHTML='<option value="">Selecionar...</option>';D.contratos.filter(c=>c.status==='ativo').forEach(c=>{mct.innerHTML+=`<option value="${c.id}">${c.cl} — ${c.placa||'?'}</option>`;});}
  const eqMobCl=document.getElementById('eq-mob-cl');
  if(eqMobCl){eqMobCl.innerHTML='<option value="">Selecionar checklist...</option>';D.checklists.forEach(c=>{eqMobCl.innerHTML+=`<option value="${c.id}">${c.nm}</option>`;});}
  const clm=document.getElementById('mn-cl-mod');if(clm){clm.innerHTML='<option value="">➕ Adicionar checklist...</option>';D.checklists.forEach(c=>{clm.innerHTML+=`<option value="${c.id}">${c.nm}</option>`;});}
  const cici=document.getElementById('ct-ci');if(cici){cici.innerHTML='<option value="">Selecionar...</option>';(D.config.ciclos||[]).forEach(c=>{cici.innerHTML+=`<option value="${c}">${c}</option>`;});}
  const mntp=document.getElementById('mn-tp');if(mntp){mntp.innerHTML='';(D.config.tiposOS||['Revisão Preventiva']).forEach(t=>{mntp.innerHTML+=`<option>${t}</option>`;});}
  const dp=document.getElementById('desp-placa');if(dp){dp.innerHTML='<option value="">Geral (sem placa)</option>';D.equips.forEach(e=>{dp.innerHTML+=`<option value="${e.placa}">${e.placa} — ${e.mk} ${e.mo}</option>`;});}
}

// ============ EQUIP ============
function addEqFotos(inp){Array.from(inp.files).forEach(f=>{_comprimirImg(f,1600,0.72,function(src,nm){var o={id:uid(),src:src,name:nm};eqFotos.push(o);rdEqFotos();_uploadFoto(src,nm,function(u){if(u&&u!==src){o.src=u;rdEqFotos();}});});});}
function rdEqFotos(){const g=document.getElementById('eq-foto-grid');if(!g)return;g.innerHTML='<label class="foto-add" for="eq-foto-inp">+</label><input type="file" id="eq-foto-inp" accept="image/*" multiple style="display:none" onchange="addEqFotos(this)">';eqFotos.forEach(f=>{const wrap=document.createElement('div');wrap.style.cssText='position:relative;display:inline-block';const i=document.createElement('img');i.src=f.src;i.className='foto-thumb';i.onclick=()=>openLB(f.src);const b=document.createElement('button');b.type='button';b.textContent='×';b.title='Excluir foto';b.style.cssText='position:absolute;top:2px;right:2px;width:20px;height:20px;border:none;border-radius:50%;background:rgba(200,16,46,.92);color:#fff;font-weight:700;cursor:pointer;line-height:1;font-size:13px;padding:0';b.onclick=(ev)=>{ev.stopPropagation();delEqFoto(f.id);};wrap.appendChild(i);wrap.appendChild(b);g.appendChild(wrap);});}
function delEqFoto(id){if(!confirm('Excluir esta foto?'))return;eqFotos=eqFotos.filter(x=>x.id!==id);rdEqFotos();}
function addEqArq(inp){Array.from(inp.files).forEach(f=>{_comprimirImg(f,1600,0.72,function(src,nm,tp,sz){eqArqs.push({id:uid(),name:nm,type:tp,size:sz,src:src});rdEqArqs();});});}
function rdEqArqs(){const el=document.getElementById('eq-arq-list');if(!el)return;el.innerHTML=eqArqs.length?eqArqs.map(a=>`<div class="doc-item"><span>${a.type&&a.type.includes('pdf')?'📄':'🖼'}</span><span class="doc-name">${a.name}</span><span style="font-size:9px;color:var(--mt)">${Math.round(a.size/1024)}KB</span><button class="btn bd btn-xs" onclick="rmEqArq('${a.id}')">×</button></div>`).join(''):'<div style="font-size:10px;color:var(--mt)">Nenhum arquivo</div>';}
function rmEqArq(id){eqArqs=eqArqs.filter(x=>x.id!==id);rdEqArqs();}
function gerarCamposParc(){
  const n=parseInt(document.getElementById('eq-nparc').value)||0;
  if(!n||n<1){toast('Informe a quantidade de parcelas primeiro','er');return;}
  if(n>120){toast('Máximo 120 parcelas','er');return;}
  const d1=document.getElementById('eq-d1parc').value;
  const tipo=document.getElementById('eq-tparc').value;
  const valorFixo=parseFloat(document.getElementById('eq-vparc').value)||0;
  const lista=document.getElementById('eq-parc-var-lista');
  if(!lista) return;
  if(tipo==='fixa'&&!valorFixo){toast('Para parcela fixa, informe o valor da parcela primeiro','er');return;}
  lista.innerHTML='';
  for(let i=1;i<=n;i++){
    let vc='';
    if(d1){
      const dt=new Date(d1);
      dt.setMonth(dt.getMonth()+(i-1));
      vc=dt.toISOString().substring(0,10);
    }
    // Fixa: preenche todos com mesmo valor; Variável: campo vazio
    const valorCampo = tipo==='fixa' ? valorFixo.toFixed(2) : '';
    const readonly = tipo==='fixa' ? 'readonly' : '';
    const bg = tipo==='fixa' ? 'var(--cd2)' : 'var(--cd)';
    lista.innerHTML+=`<div style="display:flex;gap:8px;align-items:center;margin-bottom:6px;background:var(--cd2);padding:6px;border-radius:6px">
      <span style="font-size:11px;color:var(--mt);min-width:70px">Parcela ${i}/${n}</span>
      <input type="number" id="eq-pv-val-${i}" value="${valorCampo}" placeholder="R$ 0,00" step="0.01" ${readonly} style="flex:1;padding:6px;border:1px solid var(--br);border-radius:5px;background:${bg};color:var(--tx);font-size:13px">
      <input type="date" id="eq-pv-vc-${i}" value="${vc}" style="flex:1;padding:6px;border:1px solid var(--br);border-radius:5px;background:var(--cd);color:var(--tx);font-size:13px">
    </div>`;
  }
  if(tipo==='fixa') toast(`${n} parcelas geradas com valor fixo de ${fmt(valorFixo)}!`,'ok');
  else toast(`${n} campos gerados! Preencha o valor de cada parcela.`,'ok');
}

function lancarParcelasContaPagar(eq, nParc, tParc, vParc, d1Parc, banco, situ){
  // Launch installments to Contas a Pagar (D.nfs which is the bills module)
  const desc=`${situ.toUpperCase()} - ${eq.placa} ${eq.mk} ${eq.mo} - ${banco||''}`;
  for(let i=1;i<=nParc;i++){
    let vc='';
    let vl=parseFloat(vParc)||0;
    if(tParc==='variavel'){
      const valEl=document.getElementById('eq-pv-val-'+i);
      const vcEl=document.getElementById('eq-pv-vc-'+i);
      vl=parseFloat(valEl?valEl.value:0)||0;
      vc=vcEl?vcEl.value:'';
    } else {
      if(d1Parc){
        const dt=new Date(d1Parc);
        dt.setMonth(dt.getMonth()+(i-1));
        vc=dt.toISOString().substring(0,10);
      }
    }
    D.nfs.push({
      id:uid(),
      num:`PARC-${eq.placa}-${String(i).padStart(3,'0')}`,
      forn:`Financiamento ${eq.placa}`,
      desc:`${desc} — Parcela ${i}/${nParc}`,
      vl:vl,
      vc:vc,
      dt:new Date().toISOString().substring(0,10),
      st:'pendente',
      cp:'sim',
      cat:'Financiamento',
      placa:eq.placa,
      eqId:eq.id,
      parcela:i,
      totalParc:nParc,
      travada:true
    });
  }
}

function alertaVenc(inputId, alertId){
  const val=document.getElementById(inputId).value;
  const el=document.getElementById(alertId);
  if(!el||!val) return;
  const dias=Math.ceil((new Date(val)-new Date())/(1000*60*60*24));
  if(dias<0) el.textContent='⚠️ VENCIDO há '+Math.abs(dias)+' dias';
  else if(dias<=30) el.textContent='⚠️ Vence em '+dias+' dias';
  else el.textContent='';
}

function toggleImplemento(){var s=document.getElementById('eq-tem-impl');var box=document.getElementById('eq-impl-campos');if(box)box.style.display=(s&&s.value==='sim')?'':'none';}
function toggleParc(){
  const s=document.getElementById('eq-situ').value;
  document.getElementById('eq-parc-box').style.display=['financiado','consorcio'].includes(s)?'':'none';
}
function toggleParcTipo(){
  const t=document.getElementById('eq-tparc').value;
  document.getElementById('eq-parc-fixa-box').style.display=t==='fixa'?'':'none';
  document.getElementById('eq-parc-var-box').style.display=t==='variavel'?'':'none';
}
function saveEq(){
  if(typeof _fotosEnviando!=='undefined' && _fotosEnviando>0){ toast('⏳ Aguarde — ainda enviando '+_fotosEnviando+' foto(s) ao servidor. Tente salvar daqui a alguns segundos.','er'); return; }
  const pl=document.getElementById('eq-pl').value.trim().toUpperCase();
  const ch=document.getElementById('eq-ch').value.trim();
  const rv=document.getElementById('eq-rv').value.trim();
  const crv=document.getElementById('eq-crv')?document.getElementById('eq-crv').value.trim():'';
  const empresa=document.getElementById('eq-empresa')?document.getElementById('eq-empresa').value:'';
  const mo=document.getElementById('eq-mo').value.trim();
  const an=document.getElementById('eq-an').value.trim();
  if(!pl){toast('Placa é obrigatória','er');return;}
  if(!ch){toast('Chassi é obrigatório','er');return;}
  if(!rv){toast('Renavam é obrigatório','er');return;}
  if(!mo){toast('Modelo é obrigatório','er');return;}
  if(!an){toast('Ano é obrigatório','er');return;}
  const situ=document.getElementById('eq-situ').value;
  const vaql=document.getElementById('eq-vaql').value;
  const daql=document.getElementById('eq-daql').value;
  if(!vaql){toast('Valor de aquisição é obrigatório','er');return;}
  if(!daql){toast('Data de aquisição é obrigatória','er');return;}
  if(['financiado','consorcio'].includes(situ)){
    if(!document.getElementById('eq-nparc').value){toast('Informe a quantidade de parcelas','er');return;}
    const tp=document.getElementById('eq-tparc').value;
    if(tp==='fixa'&&!document.getElementById('eq-vparc').value){toast('Informe o valor da parcela','er');return;}
  }
  const eid=document.getElementById('eq-eid').value;
  const cond=document.querySelector('input[name="eq-cond"]:checked');
  const data={
    placa:pl,ano:an,mk:document.getElementById('eq-mk').value,
    mo:mo,pr:empresa,ch:ch,
    im:document.getElementById('eq-im').value,st:document.getElementById('eq-st').value,
    km:document.getElementById('eq-km').value,hr:document.getElementById('eq-hr').value,
    cond:cond?cond.value:'novo',ob:document.getElementById('eq-ob').value,
    rv:rv,crv:crv,empresa:empresa,crlv:document.getElementById('eq-crlv').value,
    /* seguro agora é por apólice na aba Seguro */
    antt:document.getElementById('eq-antt')?document.getElementById('eq-antt').value:'',
    crono:document.getElementById('eq-crono')?document.getElementById('eq-crono').value:'',
    docMan:document.getElementById('eq-doc-man')?document.getElementById('eq-doc-man').value:'',
    docManVc:document.getElementById('eq-doc-man-vc')?document.getElementById('eq-doc-man-vc').value:'',
    vaql:vaql,daql:daql,situ:situ,
    nparc:document.getElementById('eq-nparc').value,
    tparc:document.getElementById('eq-tparc').value,
    vparc:document.getElementById('eq-vparc').value,
    parcpg:document.getElementById('eq-parcpg').value,
    d1parc:document.getElementById('eq-d1parc').value,
    banco:document.getElementById('eq-banco').value,
    dtLevant:document.getElementById('eq-dt-levant')?document.getElementById('eq-dt-levant').value:'',
    vlQuitacao:parseFloat(document.getElementById('eq-vl-quitacao')?document.getElementById('eq-vl-quitacao').value:0)||0,
    vlAtual:parseFloat(document.getElementById('eq-vl-atual')?document.getElementById('eq-vl-atual').value:0)||0,
    desval12:parseFloat(document.getElementById('eq-desval12')?document.getElementById('eq-desval12').value:0)||0,
    desval35:parseFloat(document.getElementById('eq-desval35')?document.getElementById('eq-desval35').value:0)||0,
    im_mk:document.getElementById('eq-im-mk').value,
    im_mo:document.getElementById('eq-im-mo').value,
    im_vl:document.getElementById('eq-im-vl').value,
    im_dt:document.getElementById('eq-im-dt').value,
    im_ob:document.getElementById('eq-im-ob').value,
    fotos:[...eqFotos],arqs:[...eqArqs]
  };
  const _temImpl=document.getElementById('eq-tem-impl')?document.getElementById('eq-tem-impl').value:'nao';
  data.temImpl=_temImpl;
  if(_temImpl!=='sim'){data.im='';data.im_mk='';data.im_mo='';data.im_vl='';data.im_dt='';data.im_ob='';}
  ;(function(){var _kmN=((data.km||'')+''),_hrN=((data.hr||'')+'');if(eid){var _ant=D.equips.find(function(x){return x.id===eid;})||{};if(_kmN!==((_ant.km||'')+'')||_hrN!==((_ant.hr||'')+''))data.kmDt=today();}else{if(_kmN!==''||_hrN!=='')data.kmDt=today();}})();if(eid){const idx=D.equips.findIndex(x=>x.id===eid);if(idx>-1)D.equips[idx]={...D.equips[idx],...data};}
  else{data.id=uid();D.equips.push(data);}
  document.getElementById('eq-eid').value='';
  // Parcelas em Contas a Pagar (financiado/consórcio). Regra: apaga as automáticas deste veículo e refaz.
  const _eqId = eid || (D.equips[D.equips.length-1]||{}).id;
  const _eqRef = D.equips.find(x=>x.id===_eqId) || D.equips[D.equips.length-1];
  const _antesNfs = (D.nfs||[]).length;
  D.nfs = (D.nfs||[]).filter(n=>!(n.eqId===_eqId && n.travada && n.parcela));
  const _removidas = _antesNfs - D.nfs.length;
  if(['financiado','consorcio'].includes(situ)){
    const nParc=parseInt(document.getElementById('eq-nparc').value)||0;
    if(nParc>0 && _eqRef){
      const tParc=document.getElementById('eq-tparc').value;
      const vParc=document.getElementById('eq-vparc').value;
      const d1Parc=document.getElementById('eq-d1parc').value;
      const banco=document.getElementById('eq-banco').value;
      lancarParcelasContaPagar(_eqRef, nParc, tParc, vParc, d1Parc, banco, situ);
      toast(`Veículo salvo + ${nParc} parcela(s) em Contas a Pagar!`,'ok');
    } else {
      toast(eid?'Veículo/Equipamento atualizado!':'Veículo/Equipamento salvo!');
    }
  } else {
    if(_removidas>0) toast('Veículo salvo. Parcelas anteriores removidas do Contas a Pagar.','ok');
    else toast(eid?'Veículo/Equipamento atualizado!':'Veículo/Equipamento salvo!');
  }

  sv();closeM('m-eq');rdFrota();rdFin();
}
function _podeEditarDocsVeic(){
  if(typeof ehAdminAtual==='function' && ehAdminAtual()) return true;
  if(authUser && authUser.perms && authUser.perms['doc-veiculo']) return true;
  var nome=(authUser&&authUser.nome)||'';
  var u=(D.usuarios||[]).find(function(x){return (x.nm===nome)||(x.nome===nome);});
  return !!(u && u.perms && u.perms['doc-veiculo']);
}
function _travarTabsEdicao(restrito){
  window._eqTravado = !!restrito;
  ['teq-d','teq-fin','teq-impl'].forEach(function(tid){
    var t=document.getElementById(tid); if(!t)return;
    t.querySelectorAll('input,select,textarea,button').forEach(function(el){
      if(restrito){ el.setAttribute('disabled','disabled'); el.style.opacity='.55'; }
      else { el.removeAttribute('disabled'); el.style.opacity=''; }
    });
  });
  // As 3 abas sensíveis ficam SEMPRE visíveis. Quando trancadas, ganham um
  // cadeado (🔒); o clique nelas (tratado na função stab) pede a senha de admin.
  var tabs=document.querySelectorAll('#m-eq .tabs .tab');
  tabs.forEach(function(tab){
    var oc=tab.getAttribute('onclick')||'';
    var sensivel = oc.indexOf("'teq-d'")>=0 || oc.indexOf("'teq-fin'")>=0 || oc.indexOf("'teq-impl'")>=0;
    tab.style.display='';
    if(sensivel){
      if(!tab.getAttribute('data-lbl')) tab.setAttribute('data-lbl', tab.textContent.replace(/^🔒\s*/,''));
      var base=tab.getAttribute('data-lbl');
      tab.textContent = restrito ? ('🔒 '+base) : base;
      tab.style.opacity = restrito ? '.75' : '';
    }
  });
  var banner=document.getElementById('eq-restrito-aviso');
  if(banner) banner.style.display = restrito ? 'block' : 'none';
  if(restrito){
    var docTab=Array.prototype.slice.call(tabs).find(function(t){return (t.getAttribute('onclick')||'').indexOf("'teq-doc'")>=0;});
    if(docTab && typeof stab==='function') stab(docTab,'teq-doc');
  }
}
function openEditEq(id){if(_bloqEditar('frota'))return;
  var _adm = (typeof ehAdminAtual==='function' && ehAdminAtual());
  if(_adm){
    // Admin: abre com tudo liberado, sem pedir senha.
    _abrirEditEq(id,false);
  } else if(typeof _podeEditarDocsVeic==='function' && _podeEditarDocsVeic()){
    // Usuário liberado pelo admin: Documentos/Fotos/Arquivos livres. As abas
    // Dados/Financeiro/Implemento ficam VISÍVEIS porém trancadas (🔒); ao clicar
    // nelas, o sistema pede a senha de administrador.
    _abrirEditEq(id,true);
  } else {
    // Não-admin e SEM liberação: precisa da senha de administrador para abrir.
    reqSenha(function(){ _abrirEditEq(id,false); });
  }
}
function _abrirEditEq(id, restrito){const e=D.equips.find(x=>x.id===id);if(!e)return;eqFotos=[...(e.fotos||[])];eqArqs=[...(e.arqs||[])];document.getElementById('eq-eid').value=id;document.getElementById('eq-mtitle').textContent='✏️ Editar Veíc./Equip.';[['pl','placa'],['an','ano'],['mo','mo'],['pr','pr'],['ch','ch'],['ob','ob'],['rv','rv'],['apl','apl'],['crv','crv'],['empresa','empresa']].forEach(p=>{const el=document.getElementById('eq-'+p[0]);if(el)el.value=e[p[1]]||'';});['mk','im','st'].forEach(k=>{const el=document.getElementById('eq-'+k);if(el)el.value=e[k]||(el.options&&el.options[0]?el.options[0].value:'');});['km','hr'].forEach(k=>{const el=document.getElementById('eq-'+k);if(el)el.value=e[k]||'';});['crlv','vseg'].forEach(k=>{const el=document.getElementById('eq-'+k);if(el)el.value=e[k]||'';});var _si=document.getElementById('eq-seguro-info');if(_si)_si.innerHTML=_seguroInfoHtml(e.placa);const ce=document.querySelector(`input[name="eq-cond"][value="${e.cond||'novo'}"]`);if(ce)ce.checked=true;
    const setV=(i,v)=>{const el=document.getElementById(i);if(el)el.value=(v!==undefined&&v!==null)?v:'';};
    setV('eq-dt-levant',e.dtLevant);setV('eq-vl-quitacao',e.vlQuitacao);setV('eq-vl-atual',e.vlAtual);
    setV('eq-situ',e.situ);setV('eq-banco',e.banco);setV('eq-vaql',e.vaql);setV('eq-daql',e.daql);
    setV('eq-nparc',e.nparc);setV('eq-parcpg',e.parcpg);setV('eq-tparc',e.tparc);
    setV('eq-desval12',e.desval12);setV('eq-desval35',e.desval35);
    setV('eq-vparc',e.vparc);setV('eq-d1parc',e.d1parc);setV('eq-antt',e.antt);setV('eq-crono',e.crono);
    setV('eq-im-mk',e.im_mk);setV('eq-im-mo',e.im_mo);setV('eq-im-vl',e.im_vl);setV('eq-im-dt',e.im_dt);setV('eq-im-ob',e.im_ob);
    var _ti=document.getElementById('eq-tem-impl');if(_ti)_ti.value=((e.temImpl==='sim')||(!e.temImpl&&(e.im||e.im_mk||e.im_vl)))?'sim':'nao';
    if(typeof toggleImplemento==='function')toggleImplemento();
    if(typeof calcDesvalEq==='function')setTimeout(calcDesvalEq,50);
    if(typeof toggleParc==='function')toggleParc();
    rdEqFotos();rdEqArqs();if(typeof popEmpresas==='function')popEmpresas();_travarTabsEdicao(!!restrito);document.getElementById('m-eq').classList.add('op');}
function delEq(id){reqSenha(()=>{if(!confirm('Excluir este veículo/equipamento?'))return;const ct=D.contratos.find(c=>c.eqId===id&&c.status==='ativo');if(ct){toast('Contrato ativo vinculado!','er');return;}var _e=D.equips.find(x=>x.id===id);if(typeof auditarExclusao==='function')auditarExclusao('frota','Excluiu veículo: '+((_e&&_e.placa)||id));D.equips=D.equips.filter(x=>x.id!==id);sv();rdFrota();toast('Excluído.');});}
function chgStatus(id){const e=D.equips.find(x=>x.id===id);if(!e)return;const opts=['disponivel','alocado','imobilizado','vendido','uso_empresa'];const lbl={disponivel:'Disponível',alocado:'Alocado',imobilizado:'Imobilizado',vendido:'Vendido',uso_empresa:'Uso Empresa'};const cur=opts.indexOf(e.st);const next=opts[(cur+1)%opts.length];if(!confirm(`Alterar status de ${lbl[e.st]} para ${lbl[next]}?`))return;e.st=next;sv();rdFrota();toast('Status: '+lbl[next]);}
// ============ MEDIÇÃO MANUAL (autorização por placa + geração pelo Financeiro) ============
function _ehFinanceiro(){
  if(typeof ehAdminAtual==='function' && ehAdminAtual()) return true;
  var pf=(authUser&&(authUser.perfil||authUser.pf))||'';
  if(pf==='financeiro') return true;
  var nome=(authUser&&authUser.nome)||'';
  var u=(D.usuarios||[]).find(function(x){return (x.nm===nome)||(x.nome===nome);});
  return !!(u && ((u.pf==='financeiro')||(u.perfil==='financeiro')));
}
function _popClientesMM(selId,val){
  var sel=document.getElementById(selId); if(!sel)return;
  sel.innerHTML='<option value="">Selecionar cliente cadastrado...</option>';
  (D.clientes||[]).forEach(function(c){ var nm=c.nome||c.nm||c.razao||c.fantasia||'?'; sel.innerHTML+='<option value="'+c.id+'">'+nm+'</option>'; });
  if(val)sel.value=val;
}
function openMedManAut(id){
  if(typeof ehAdminAtual==='function' && ehAdminAtual()){ _abrirMedManAut(id); }
  else { reqSenha(function(){ _abrirMedManAut(id); }); }
}
function _abrirMedManAut(id){
  var e=D.equips.find(function(x){return x.id===id;}); if(!e)return;
  if(e.st==='vendido'){ toast('Veículo vendido não pode ser autorizado.','er'); return; }
  document.getElementById('mm-aut-eid').value=id;
  document.getElementById('mm-aut-info').innerHTML='<b>'+e.placa+'</b> — '+(e.mk||'')+' '+(e.mo||'');
  _popClientesMM('mm-aut-cli',(e.medManual&&e.medManual.clienteId)||'');
  document.getElementById('mm-aut-venc').value=(e.medManual&&e.medManual.venc)||'';
  document.getElementById('mm-aut-obs').value=(e.medManual&&e.medManual.obs)||'';
  openM('m-mm-aut');
}
function salvarMedManAut(){
  var id=document.getElementById('mm-aut-eid').value;
  var e=D.equips.find(function(x){return x.id===id;}); if(!e)return;
  var cliId=document.getElementById('mm-aut-cli').value;
  var venc=document.getElementById('mm-aut-venc').value;
  if(!cliId){ toast('Selecione o cliente','er'); return; }
  if(!venc){ toast('Informe o vencimento/prazo','er'); return; }
  var c=(D.clientes||[]).find(function(x){return x.id===cliId;});
  var nm=(c&&(c.nome||c.nm||c.razao))||'';
  e.medManual={venc:venc,clienteId:cliId,cliente:nm,obs:document.getElementById('mm-aut-obs').value,por:(authUser&&authUser.nome)||'',em:(typeof today==='function'?today():new Date().toISOString().slice(0,10))};
  if(e.st==='disponivel'||e.st==='alocado'||!e.st){ e.st='alocado'; }
  if(typeof auditar==='function')auditar('CRIACAO','frota','Autorizou Medição Manual: '+e.placa+' (cliente '+nm+', venc '+venc+')');
  sv(); closeM('m-mm-aut'); if(typeof rdFrota==='function')rdFrota(); toast('Medição manual autorizada. Placa → Alocado.','ok');
}
function finalizarMedMan(id){
  reqSenha(function(){
    var e=D.equips.find(function(x){return x.id===id;}); if(!e)return;
    if(!e.medManual){ toast('Esta placa não tem autorização ativa.','er'); return; }
    if(!confirm('Finalizar a autorização de medição manual de '+e.placa+'?\nA placa volta para Disponível (se não houver contrato ativo).'))return;
    var nm=(e.medManual&&e.medManual.cliente)||'';
    delete e.medManual;
    var temCt=(D.contratos||[]).find(function(c){return c.eqId===id && c.status==='ativo';});
    if(!temCt && e.st==='alocado'){ e.st='disponivel'; }
    if(typeof auditar==='function')auditar('ALTERACAO','frota','Finalizou Medição Manual: '+e.placa+' (cliente '+nm+')');
    sv(); if(typeof rdFrota==='function')rdFrota(); toast('Autorização finalizada.','ok');
  });
}
function openMedManGer(id){
  var e=D.equips.find(function(x){return x.id===id;}); if(!e)return;
  if(!e.medManual){ toast('Placa não autorizada para medição manual. Peça ao administrador.','er'); return; }
  if(!_ehFinanceiro()){ toast('Apenas o Financeiro (ou admin) pode gerar medição manual.','er'); return; }
  document.getElementById('mm-ger-eid').value=id;
  document.getElementById('mm-ger-info').innerHTML='<b>'+e.placa+'</b> — '+(e.mk||'')+' '+(e.mo||'')+'<br>Cliente: <b>'+(e.medManual.cliente||'-')+'</b> · Autorizado até '+(e.medManual.venc||'-');
  document.getElementById('mm-ger-ms').value='';
  document.getElementById('mm-ger-vc').value=e.medManual.venc||'';
  document.getElementById('mm-ger-vl').value='';
  document.getElementById('mm-ger-dc').value='';
  document.getElementById('mm-ger-obs').value='';
  openM('m-mm-ger');
}
function salvarMedManGer(){
  var id=document.getElementById('mm-ger-eid').value;
  var e=D.equips.find(function(x){return x.id===id;}); if(!e)return;
  if(!e.medManual){ toast('Autorização não encontrada.','er'); return; }
  if(!_ehFinanceiro()){ toast('Apenas o Financeiro pode gerar.','er'); return; }
  var vl=parseFloat(document.getElementById('mm-ger-vl').value)||0;
  var dc=parseFloat(document.getElementById('mm-ger-dc').value)||0;
  var ms=document.getElementById('mm-ger-ms').value;
  var vc=document.getElementById('mm-ger-vc').value;
  if(!ms){ toast('Informe o mês/referência','er'); return; }
  if(!vc){ toast('Informe o vencimento','er'); return; }
  if(vl<=0){ toast('Informe o valor da medição','er'); return; }
  D.medicoes.push({id:uid(),ctId:'',manual:true,numMed:((D.medicoes||[]).filter(function(x){return x.manual&&x.placa===e.placa;}).length+1),cl:(e.medManual.cliente||''),clienteId:(e.medManual.clienteId||''),placa:(e.placa||''),ms:ms,de:'',at:'',hr:'',he:0,vhe:0,vl:vl,dc:dc,total:vl-dc,vc:vc,st:'pendente',obs:document.getElementById('mm-ger-obs').value,fluxo:'sim'});
  if(typeof auditar==='function')auditar('CRIACAO','medicoes','Medição MANUAL gerada: '+(e.medManual.cliente||'')+' ('+e.placa+') '+fmt(vl-dc));
  sv(); if(window.emailAutoSe)window.emailAutoSe('medicao',D.medicoes[D.medicoes.length-1]);
  closeM('m-mm-ger'); if(typeof rdFrota==='function')rdFrota(); if(typeof updPendCnt==='function')updPendCnt(); if(typeof rp==='function')rp(cur);
  toast('Medição manual gerada! Entrou no Financeiro.','ok');
}
function _btnsMedMan(e){
  var admin=(typeof ehAdminAtual==='function' && ehAdminAtual());
  var aut=!!e.medManual;
  var out='';
  if(admin){
    out+=' <button class="btn '+(aut?'bp':'bw')+' btn-xs" onclick="openMedManAut(\''+e.id+'\')" title="'+(aut?'Medição manual AUTORIZADA — clique para editar':'Autorizar medição manual')+'">📋</button>';
    if(aut) out+=' <button class="btn bg btn-xs" onclick="finalizarMedMan(\''+e.id+'\')" title="Finalizar autorização (volta a Disponível)">✔</button>';
  }
  return out;
}

// ============ MANUTENÇÃO ============
function togProxRev(){var tp=document.getElementById('mn-tp');var row=document.getElementById('mn-prox-rev-row');if(!tp||!row)return;var ehPrev=(tp.value||'').toLowerCase().indexOf('preventiva')>=0;row.style.display=ehPrev?'':'none';}
function autoFillEq(){const sel=document.getElementById('mn-eq');const eq=D.equips.find(e=>e.id===sel.value);if(!eq)return;var kmA=kmAtualVeic(eq),hrA=hrAtualVeic(eq);if(kmA)document.getElementById('mn-km').value=kmA;if(hrA)document.getElementById('mn-hr').value=hrA;var tp=document.getElementById('mn-tp');var ehPrev=tp&&(tp.value||'').toLowerCase().indexOf('preventiva')>=0;if(ehPrev){document.getElementById('mn-pkm').value=kmA+(D.config.rkm||10000);document.getElementById('mn-phr').value=hrA+(D.config.rhr||500);}}
function addLancManual(){const desc=prompt('Descrição:');if(!desc)return;const qtd=parseFloat(prompt('Quantidade:','1')||1);const val=parseFloat(prompt('Valor unitário (R$):','0')||0);const tipo=confirm('É PEÇA?\nOK=Peça / Cancelar=Serviço')?'Peça':'Serviço';mnLancs.push({id:uid(),desc,qtd,val,tipo,fonte:'manual'});rdMLanc();}
function addLancEstq(){const disp=D.estoque.filter(e=>e.qt>0);if(!disp.length){toast('Sem itens em estoque','er');return;}const opts=disp.map((e,i)=>`${i+1}. [${e.cd||'?'}] ${e.ds} (${e.qt}${e.un} / ${fmt(e.cv)})`);const s=prompt('Selecione o item:\n'+opts.join('\n'));const idx=parseInt(s)-1;if(isNaN(idx)||idx<0||idx>=disp.length)return;const item=disp[idx];const qtd=parseFloat(prompt('Quantidade:','1')||0);if(!qtd||qtd>item.qt){toast('Qtd inválida ou acima do estoque','er');return;}mnLancs.push({id:uid(),desc:item.ds,qtd,val:item.cv,tipo:'Peça',fonte:'estoque',estqId:item.id});item.qt-=qtd;sv();rdMLanc();}
function rdMLanc(){const el=document.getElementById('mn-lanc-list');if(!el)return;const tot=mnLancs.reduce((s,l)=>s+l.qtd*l.val,0);el.innerHTML=mnLancs.length?mnLancs.map(l=>`<div class="lanc-row"><div><div style="font-size:11px;font-weight:500">${l.desc}${l.fonte==='estoque'?'<span style="font-size:8px;color:var(--gn);margin-left:5px">📦</span>':''}</div><div style="font-size:9px;color:var(--mt)">${l.tipo} · ${l.qtd}x · ${fmt(l.val)}</div></div><div style="display:flex;align-items:center;gap:5px"><span style="font-family:'Barlow Condensed';font-size:12px;font-weight:700;color:${l.tipo==='Peça'?'var(--bl)':'var(--pu)'}">${fmt(l.qtd*l.val)}</span><button class="btn bd btn-xs" onclick="rmLanc('${l.id}')">×</button></div></div>`).join(''):'<div class="empty"><div class="ei">🔩</div>Nenhum item</div>';document.getElementById('mn-tot').textContent=fmt(tot);}
function rmLanc(id){const l=mnLancs.find(x=>x.id===id);if(l&&l.fonte==='estoque'&&l.estqId){const ei=D.estoque.find(e=>e.id===l.estqId);if(ei)ei.qt+=l.qtd;sv();}mnLancs=mnLancs.filter(x=>x.id!==id);rdMLanc();}
function popPneusOS(){
  var sel=document.getElementById('mn-pneu-sel'); if(!sel) return;
  var usados=mnPneus.map(function(p){return p.id;});
  sel.innerHTML='<option value="">Selecionar pneu do estoque...</option>';
  (D.pneus||[]).filter(function(p){return p.st==='estoque' && usados.indexOf(p.id)<0;}).forEach(function(p){
    sel.innerHTML+='<option value="'+p.id+'">'+(p.num||'?')+' — '+(p.mk||'')+' '+(p.med||'')+'</option>';
  });
}
function addPneuOS(){
  var sel=document.getElementById('mn-pneu-sel');
  var id=sel?sel.value:''; if(!id){toast('Selecione um pneu do estoque.','er');return;}
  var p=(D.pneus||[]).find(function(x){return x.id===id;});
  if(!p||p.st!=='estoque'){toast('Pneu indisponível no estoque.','er');return;}
  mnPneus.push({id:p.id,num:p.num,mk:p.mk,med:p.med});
  popPneusOS(); rdMnPneus();
}
function rmPneuOS(id){ mnPneus=mnPneus.filter(function(p){return p.id!==id;}); popPneusOS(); rdMnPneus(); }
function processarPneusOS(osId, osNum, placa){
  if(!Array.isArray(D.pneus)) D.pneus=[];
  if(!Array.isArray(D.pneus_pend)) D.pneus_pend=[];
  if(!Array.isArray(D.pneus_hist)) D.pneus_hist=[];
  var idsAtuais=mnPneus.map(function(p){return p.id;});
  var hoje=(typeof today==='function')?today():new Date().toISOString().slice(0,10);
  // aplicar os pneus escolhidos que ainda não estão aplicados nesta OS
  mnPneus.forEach(function(mp){
    var p=D.pneus.find(function(x){return x.id===mp.id;});
    if(!p) return;
    if(!(p.st==='aplicado' && p.osId===osId)){
      p.st='aplicado'; p.placa=placa; p.osId=osId; p.osNum=osNum; p.dtAplic=hoje; p.local='Placa '+(placa||'');
      D.pneus_hist.push({num:p.num,tipo:'aplicação',destino:(placa||'')+' (OS '+osNum+')',dt:hoje});
    }
  });
  // devolver ao estoque os pneus que estavam aplicados nesta OS mas foram retirados da lista
  D.pneus.forEach(function(p){
    if(p.st==='aplicado' && p.osId===osId && idsAtuais.indexOf(p.id)<0){
      p.st='estoque'; p.placa=''; p.osId=''; p.osNum=''; p.local='Estoque';
      D.pneus_hist.push({num:p.num,tipo:'retorno ao estoque',destino:'Estoque (OS '+osNum+' editada)',dt:hoje});
    }
  });
  // total aplicado nesta OS = nº de pneus retirados da placa que precisam dar entrada
  var totalAplicados=D.pneus.filter(function(p){return p.st==='aplicado' && p.osId===osId;}).length;
  var pend=D.pneus_pend.find(function(x){return x.osId===osId;});
  if(totalAplicados>0){
    if(pend){
      pend.qtd=totalAplicados; pend.placa=placa; pend.osNum=osNum;
      if(pend.feitos>pend.qtd)pend.feitos=pend.qtd;
      pend.st=pend.feitos>=pend.qtd?'resolvida':'pendente';
    } else {
      D.pneus_pend.push({id:uid(),osId:osId,osNum:osNum,placa:placa,qtd:totalAplicados,feitos:0,data:hoje,st:'pendente'});
    }
  } else if(pend && (pend.feitos||0)===0){
    D.pneus_pend=D.pneus_pend.filter(function(x){return x.osId!==osId;});
  }
  if(typeof updPneuPendCnt==='function')updPneuPendCnt();
}
function rdMnPneus(){
  var escH=function(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
  var el=document.getElementById('mn-pneus-list'); if(!el) return;
  if(!mnPneus.length){ el.innerHTML='<div style="font-size:10px;color:var(--mt);padding:4px 0">Nenhum pneu lançado.</div>'; return; }
  el.innerHTML='<div style="font-size:9px;color:var(--mt);margin-bottom:4px">'+mnPneus.length+' pneu(s) — saem do estoque ao salvar e geram '+mnPneus.length+' entrada(s) pendente(s)</div>'+mnPneus.map(function(p){
    return '<div class="lanc-row"><div><div style="font-size:11px;font-weight:500">🛞 '+escH(p.num||'?')+' <span style="font-size:8px;color:var(--gn)">📦 estoque</span></div><div style="font-size:9px;color:var(--mt)">'+escH(p.mk||'')+' · '+escH(p.med||'')+'</div></div><button class="btn bd btn-xs" onclick="rmPneuOS(\''+p.id+'\')">×</button></div>';
  }).join('');
}
function loadClMod(){
  const sel=document.getElementById('mn-cl-mod');
  const cl=D.checklists.find(c=>c.id===sel.value);
  if(!cl){return;}
  if(mnClIs.some(function(i){return (i.grupo||'')===cl.nm;})){ toast('Este checklist já foi adicionado.','er'); sel.value=''; return; }
  (cl.items||[]).forEach(function(i){ mnClIs.push({id:uid(),txt:i.txt,ck:false,grupo:cl.nm}); });
  sel.value='';
  rdMCl();
  toast('Checklist "'+cl.nm+'" adicionado.','ok');
}
function rmGrupoCl(grupo){
  mnClIs=mnClIs.filter(function(i){return (i.grupo||'Itens')!==grupo;});
  rdMCl();
}
function rdMCl(){
  var escH=function(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
  const el=document.getElementById('mn-cl-list');if(!el)return;
  if(!mnClIs.length){el.innerHTML='<div class="empty"><div class="ei">☑️</div>Selecione um ou mais checklists acima</div>';return;}
  const ck=mnClIs.filter(i=>i.ck).length;
  var grupos={}, ordem=[];
  mnClIs.forEach(function(i){var g=i.grupo||'Itens';if(!grupos[g]){grupos[g]=[];ordem.push(g);}grupos[g].push(i);});
  var html='<div style="font-size:9px;color:var(--mt);margin-bottom:6px">'+ck+'/'+mnClIs.length+' marcados · '+ordem.length+' checklist(s)</div>';
  ordem.forEach(function(g){
    html+='<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center;background:var(--cd);border:1px solid var(--br);border-radius:4px 4px 0 0;padding:4px 8px"><span style="font-size:10px;font-weight:700;color:var(--cy)">📋 '+escH(g)+'</span><button class="btn bd btn-xs" data-g="'+escH(g)+'" onclick="rmGrupoCl(this.dataset.g)" title="Remover este checklist">×</button></div>';
    html+=grupos[g].map(function(i){return '<div style="display:flex;align-items:center;gap:6px;padding:5px 7px;background:var(--cd2);border:1px solid var(--br);border-top:none"><div style="width:13px;height:13px;border-radius:2px;border:2px solid '+(i.ck?'var(--gn)':'var(--br2)')+';background:'+(i.ck?'var(--gn)':'transparent')+';cursor:pointer;flex-shrink:0" onclick="togCl(\''+i.id+'\')"></div><span style="font-size:11px;'+(i.ck?'text-decoration:line-through;color:var(--mt)':'')+'">'+escH(i.txt)+'</span></div>';}).join('');
    html+='</div>';
  });
  el.innerHTML=html;
}
function togCl(id){const i=mnClIs.find(x=>x.id===id);if(i){i.ck=!i.ck;rdMCl();}}
function addFotos(inp){Array.from(inp.files).forEach(f=>{_comprimirImg(f,1600,0.72,function(src,nm){var o={id:uid(),src:src,name:nm};mnFotos.push(o);rdMFotos();_uploadFoto(src,nm,function(u){if(u&&u!==src){o.src=u;rdMFotos();}});});});}
function rdMFotos(){const g=document.getElementById('mn-foto-grid');if(!g)return;g.innerHTML='<label class="foto-add" for="mn-foto-inp">+</label><input type="file" id="mn-foto-inp" accept="image/*" multiple style="display:none" onchange="addFotos(this)">';mnFotos.forEach(f=>{const i=document.createElement('img');i.src=f.src;i.className='foto-thumb';i.onclick=()=>openLB(f.src);g.appendChild(i);});}
function saveMn(){if(typeof _fotosEnviando!=='undefined' && _fotosEnviando>0){ toast('⏳ Aguarde — ainda enviando '+_fotosEnviando+' foto(s) ao servidor. Tente salvar daqui a alguns segundos.','er'); return; }const eqId=document.getElementById('mn-eq').value;
  if(getEmpresas().length===0){toast('Cadastre ao menos uma empresa antes de gerar OS (botão Empresas).','er');return;}
  if(!eqId){toast('Selecione o veículo/equipamento/placa da frota','er');return;}const eq=D.equips.find(e=>e.id===eqId);
  const empresasCad=getEmpresas().map(e=>e.nome);
  if(eq&&(!eq.empresa||!empresasCad.includes(eq.empresa))){toast('Este veículo não está vinculado a uma empresa cadastrada. Edite o veículo e defina a empresa proprietária.','er');return;}const custo=document.querySelector('input[name="mn-custo"]:checked');const tot=mnLancs.reduce((s,l)=>s+l.qtd*l.val,0);const dados={eqId,eqLbl:eq?`${eq.placa} ${eq.mo}`:'-',placa:eq?eq.placa:'-',tipo:document.getElementById('mn-tp').value,en:document.getElementById('mn-en').value,sa:document.getElementById('mn-sa').value,km:document.getElementById('mn-km').value,hr:document.getElementById('mn-hr').value,pkm:document.getElementById('mn-pkm').value,phr:document.getElementById('mn-phr').value,custo:custo?custo.value:'mh3',status:document.getElementById('mn-status').value,resp:(document.getElementById('mn-re').value==='__manual__'?(document.getElementById('mn-re-manual').value||'').trim():document.getElementById('mn-re').value),ob:document.getElementById('mn-ob').value,lancs:[...mnLancs],checklist:[...mnClIs],fotos:[...mnFotos],total:tot};const _eid=(document.getElementById('mn-eid')||{}).value||'';if(_eid){const idx=D.manutencoes.findIndex(x=>x.id===_eid);if(idx<0){toast('OS não encontrada.','er');return;}if(D.manutencoes[idx].status==='concluida'){toast('Esta OS já está concluída e não pode ser editada.','er');return;}D.manutencoes[idx]=Object.assign({},D.manutencoes[idx],dados);processarPneusOS(D.manutencoes[idx].id,D.manutencoes[idx].osNum,dados.placa);auditar('ALTERACAO','manutencoes','OS '+(D.manutencoes[idx].osNum||'')+' editada');sv();if(window.emailAutoSe)window.emailAutoSe('os',D.manutencoes[idx]);closeM('m-mn');toast('OS '+(D.manutencoes[idx].osNum||'')+' atualizada!','ok');updPendCnt();rp(cur);return;}const osNum=D._pendingOsNum||(nextNum('os'));delete D._pendingOsNum;const m=Object.assign({id:uid(),osNum,finStatus:'pendente'},dados);D.manutencoes.push(m);processarPneusOS(m.id,m.osNum,dados.placa);auditar('CRIACAO','manutencoes','OS '+osNum+' criada');sv();if(window.emailAutoSe)window.emailAutoSe('os',m);closeM('m-mn');toast(`OS ${osNum} salva!`);updPendCnt();rp(cur);}
function editMn(id){if(_bloqEditar('manut'))return;
  var m=D.manutencoes.find(function(x){return x.id===id;}); if(!m) return;
  if(m.status==='concluida'){ toast('Esta OS está CONCLUÍDA e não pode mais ser editada. Para alterar, exclua e recrie.','er'); return; }
  popSels();
  var setV=function(i,v){var el=document.getElementById(i);if(el)el.value=(v==null?'':v);};
  document.getElementById('mn-eid').value=m.id;
  document.getElementById('mn-num-label').textContent=m.osNum||'';
  delete D._pendingOsNum;
  setV('mn-eq',m.eqId); setV('mn-tp',m.tipo); setV('mn-en',m.en); setV('mn-sa',m.sa);
  setV('mn-km',m.km); setV('mn-hr',m.hr); setV('mn-pkm',m.pkm); setV('mn-phr',m.phr); if(typeof togProxRev==='function')togProxRev();
  var rc=document.querySelector('input[name="mn-custo"][value="'+(m.custo||'mh3')+'"]'); if(rc)rc.checked=true;
  setV('mn-status',m.status||'aberta');
  var reSel=document.getElementById('mn-re');
  var existe=reSel && Array.prototype.some.call(reSel.options,function(o){return o.value===m.resp && o.value!=='' && o.value!=='__manual__';});
  if(m.resp && existe){ reSel.value=m.resp; }
  else if(m.resp){ if(reSel)reSel.value='__manual__'; var man=document.getElementById('mn-re-manual'); if(man)man.value=m.resp; }
  else if(reSel){ reSel.value=''; }
  if(typeof toggleRespManual==='function')toggleRespManual();
  setV('mn-ob',m.ob);
  mnLancs=(m.lancs||[]).slice(); mnClIs=(m.checklist||[]).slice(); mnFotos=(m.fotos||[]).slice();
  mnPneus=(D.pneus||[]).filter(function(p){return p.st==='aplicado' && p.osId===m.id;}).map(function(p){return {id:p.id,num:p.num,mk:p.mk,med:p.med};});
  if(typeof rdMLanc==='function')rdMLanc();
  if(typeof rdMCl==='function')rdMCl();
  if(typeof rdMFotos==='function')rdMFotos();
  if(typeof popPneusOS==='function')popPneusOS();
  if(typeof rdMnPneus==='function')rdMnPneus();
  document.getElementById('m-mn').classList.add('op');
}
function delMn(id){reqSenha(()=>{if(!confirm('Excluir esta OS?'))return;const m=D.manutencoes.find(x=>x.id===id);if(m)m.lancs.forEach(l=>{if(l.fonte==='estoque'&&l.estqId){const e=D.estoque.find(x=>x.id===l.estqId);if(e)e.qt+=l.qtd;}});var _hj=(typeof today==='function')?today():new Date().toISOString().slice(0,10);(D.pneus||[]).forEach(function(p){if(p.st==='aplicado'&&p.osId===id){p.st='estoque';p.placa='';p.osId='';p.osNum='';p.local='Estoque';if(Array.isArray(D.pneus_hist))D.pneus_hist.push({num:p.num,tipo:'retorno ao estoque',destino:'Estoque (OS excluída)',dt:_hj});}});if(Array.isArray(D.pneus_pend))D.pneus_pend=D.pneus_pend.filter(function(x){return x.osId!==id;});D.manutencoes=D.manutencoes.filter(x=>x.id!==id);sv();rdManut();if(typeof rdPneus==='function')rdPneus();toast('OS excluída.');});}
function openPrintOS(id){document.getElementById('print-os-id').value=id;openM('m-print-os');}
function execPrintOS(){const id=document.getElementById('print-os-id').value;const m=D.manutencoes.find(x=>x.id===id);if(!m)return;const fotos=document.getElementById('pi-fotos').checked;const valor=document.getElementById('pi-valor').checked;const clCheck=document.getElementById('pi-cl').checked;const tipo=document.querySelector('input[name="pi-tipo"]:checked').value;closeM('m-print-os');document.getElementById('view-title').textContent=`🔧 OS ${m.osNum} — ${m.eqLbl}`;let html=`<div style="text-align:center;margin-bottom:14px"><div style="font-family:'Bebas Neue';font-size:32px;color:var(--red)">MH3 RENTAL LTDA</div><div style="font-size:9px;color:var(--mt)">ORDEM DE SERVIÇO — ${m.osNum}</div></div>`;html+=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">`;html+=`<div class="rel-card"><div class="stat-label">Nº OS</div><div class="stat-value" style="color:var(--cy)">${m.osNum}</div></div>`;html+=`<div class="rel-card"><div class="stat-label">Tipo</div><div class="stat-value">${m.tipo}</div></div>`;html+=`<div class="rel-card"><div class="stat-label">Veículo/Equipamento</div><div class="stat-value"><span class="tag-p">${m.placa}</span></div></div>`;html+=`<div class="rel-card"><div class="stat-label">Status</div>${bdg(m.status)}</div>`;html+=`<div class="rel-card"><div class="stat-label">Entrada / Saída</div><div class="stat-value">${m.en||'-'} → ${m.sa||'Em aberto'}</div></div>`;html+=`<div class="rel-card"><div class="stat-label">KM / Horímetro</div><div class="stat-value">${m.km||'-'} / ${m.hr||'-'}h</div></div>`;if(tipo!=='simples'){html+=`<div class="rel-card"><div class="stat-label">Próxima Revisão</div><div class="stat-value">${m.pkm||'-'}km / ${m.phr||'-'}h</div></div><div class="rel-card"><div class="stat-label">Responsável</div><div class="stat-value">${m.resp||'-'}</div></div>`;}html+=`<div class="rel-card"><div class="stat-label">Custo Para</div><div class="stat-value">${m.custo==='cliente'?'Cliente':'MH3'}</div></div>`;html+=`</div>`;if(clCheck&&m.checklist&&m.checklist.length){html+=`<div class="rel-card" style="margin-bottom:8px"><div style="font-size:9px;font-weight:700;color:var(--mt);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">CHECKLIST (${m.checklist.filter(i=>i.ck).length}/${m.checklist.length})</div>${m.checklist.map(i=>`<div style="display:flex;align-items:center;gap:5px;padding:3px 0;border-bottom:1px solid var(--br)"><span style="color:${i.ck?'var(--gn)':'var(--mt)'};font-size:12px">${i.ck?'✓':'○'}</span><span style="font-size:10px;${i.ck?'text-decoration:line-through;color:var(--mt)':''}">${i.txt}</span></div>`).join('')}</div>`;}if(tipo!=='simples'&&m.lancs&&m.lancs.length){html+=`<div class="rel-card" style="margin-bottom:8px"><div style="font-size:9px;font-weight:700;color:var(--mt);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">PRODUTOS / PEÇAS</div>${m.lancs.map(l=>`<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--br)"><div><span style="font-size:10px;font-weight:500">${l.desc}</span><span style="font-size:9px;color:var(--mt);margin-left:5px">${l.tipo} · ${l.qtd}x</span></div>${valor?`<span style="font-size:11px;font-weight:600">${fmt(l.qtd*l.val)}</span>`:''}</div>`).join('')}${valor?`<div style="text-align:right;margin-top:6px;font-family:'Bebas Neue';font-size:18px;color:var(--gn)">TOTAL: ${fmt(m.total)}</div>`:''}</div>`;}if(fotos&&m.fotos&&m.fotos.length){html+=`<div class="rel-card"><div style="font-size:9px;font-weight:700;color:var(--mt);text-transform:uppercase;letter-spacing:1px;margin-bottom:6px">FOTOS</div><div class="foto-grid">${m.fotos.map(f=>`<img class="foto-thumb" src="${f.src}" onclick="openLB('${f.src}')">`).join('')}</div></div>`;}if(m.ob)html+=`<div class="rel-card"><div class="stat-label">Observações</div><div style="font-size:10px;margin-top:4px">${m.ob}</div></div>`;document.getElementById('view-body').innerHTML=html;openM('m-view');}

