  const _inad=_inadL.reduce((s,x)=>s+(x.total||0),0), _lucro=rc-dp;
  _setK('kpi-ocup',_ocup+'%');_setK('kpi-inad',fmtk(_inad));_setK('kpi-lucro',fmtk(_lucro));
