// ---- LOGIN ---- (autenticacao real via MySQL)

// ---- VERIFICA SE O SERVIDOR ESTÁ ONLINE NA TELA DE LOGIN ----
async function verificarServidorLogin(){
  const msg=document.getElementById('lg-offline-msg');
  if(!msg)return;
  if(typeof authToken!=='undefined' && authToken){window._verifSrvRodando=false;return;}
  if(window._verifSrvRodando)return;
  window._verifSrvRodando=true;
  async function pingar(ms){
    try{
      const c=new AbortController();
      const tm=setTimeout(()=>c.abort(),ms);
      const res=await fetch('api.php?action=ping',{signal:c.signal,cache:'no-store'});
      clearTimeout(tm);
      const r=await res.json();
      return !!(r&&r.ok);
    }catch(e){return false;}
  }
  let ok=await pingar(8000);
  if(!ok){
    msg.style.display='block';
    msg.innerHTML='🔄 Reconectando ao servidor...';
    for(let i=0;i<3 && !ok;i++){
      await new Promise(r=>setTimeout(r,3000));
      ok=await pingar(6000);
    }
  }
  window._verifSrvRodando=false;
  if(ok){
    msg.style.display='none';
  }else{
    msg.innerHTML='⚠️ Sistema offline — verifique a internet. <a href="#" onclick="window._verifSrvRodando=false;verificarServidorLogin();return false;" style="color:#d97706;text-decoration:underline;font-weight:700;">Tentar de novo</a>';
    msg.style.display='block';
    setTimeout(function(){if(typeof authToken!=='undefined'&&authToken)return;var m=document.getElementById('lg-offline-msg');if(m&&m.style.display!=='none'){verificarServidorLogin();}},8000);
  }
}

// ---- SALVAR USUÁRIO/SENHA NA TELA DE LOGIN ----
function salvarCredLogin(){
  try{
    const c=document.getElementById('lg-salvar');
    if(c && c.checked){
      const u=document.getElementById('lg-user').value;
      const p=document.getElementById('lg-pass').value;
      localStorage.setItem('mh3_cred', btoa(unescape(encodeURIComponent(JSON.stringify({u,p})))));
    } else {
      localStorage.removeItem('mh3_cred');
    }
  }catch(e){}
}
function carregarCredLogin(){
  try{
    const raw=localStorage.getItem('mh3_cred');
    if(!raw)return;
    const obj=JSON.parse(decodeURIComponent(escape(atob(raw))));
    const eu=document.getElementById('lg-user'), ep=document.getElementById('lg-pass'), ec=document.getElementById('lg-salvar');
    if(eu&&obj.u)eu.value=obj.u;
    if(ep&&obj.p)ep.value=obj.p;
    if(ec)ec.checked=true;
  }catch(e){}
}

async function fazerLogin() {
    const btn  = document.getElementById('lg-btn');
    const erro = document.getElementById('login-erro');
    const user = (document.getElementById('lg-user').value || '').trim();
    const pass = document.getElementById('lg-pass').value || '';

    erro.style.display = 'none';

    if (!user || !pass) {
        erro.textContent = 'Preencha usuário e senha';
        erro.style.display = 'block';
        return;
    }

    btn.textContent = 'Entrando...';
    btn.disabled = true;

    // Credenciais locais de fallback (caso o banco esteja fora)
    const usuariosLocal = {
        'noninho':   {senha:'mh3@2025', nome:'Noninho Fraga',   perfil:'admin'},
        'arthur':    {senha:'mh3@2025', nome:'Arthur',          perfil:'motorista'}
    };

    // 1) Tenta login REAL no servidor (MySQL) — gera token válido
    let servidorRespondeu = false;
    try {
        const res = await fetch('api.php?action=login', {
            method: 'POST',
            headers: {'Content-Type':'application/json'},
            body: JSON.stringify({login: user.toLowerCase(), senha: pass})
        });
        servidorRespondeu = true;
        const r = await res.json();
        if (r.ok && r.token) {
            authToken = r.token;
            authUser  = {nome: r.nome, perfil: r.perfil, perms: r.permissoes||null, login: user.toLowerCase()};
            localStorage.setItem('mh3_token', authToken);
            localStorage.setItem('mh3_user', JSON.stringify(authUser));
            salvarCredLogin();
            _mostrarOverlayCarregando('Carregando dados do servidor...', false);
            entrarSistema(r.nome, r.perfil);
            syncAtivo = true;
            mostrarStatusConexao(true);
            // TRAVA DE LOGIN: segura na tela de carregamento ate baixar o estado atual do servidor
            await _carregarInicialBloqueante();
            return;
        }
        // Servidor respondeu mas não autenticou (ex: usuário criado no app, ainda não no servidor)
        // NÃO retorna aqui — cai na verificação local (usuários criados + fixos) abaixo.
    } catch(e) {
        // Mostrar erro real para diagnóstico
        window._loginErro = e.message + ' | ' + e.name;
    }

    // ONLINE-ONLY: este sistema NÃO trabalha offline.
    // Servidor respondeu mas não autenticou -> usuário/senha errado.
    // Servidor não respondeu (sem internet / servidor fora) -> avisa e NÃO entra.
    if (servidorRespondeu) {
        erro.textContent = 'Usuário ou senha incorretos';
    } else {
        erro.textContent = '⚠️ Sem conexão com o servidor. Este sistema só funciona online — verifique a internet e tente novamente.';
    }
    erro.style.display = 'block';
    btn.textContent = 'Entrar no Sistema';
    btn.disabled = false;
    return;
}

function _mostrarOverlayCarregando(msg, comBotoes){
  if(!document.getElementById('mh3-spin-style')){ var st=document.createElement('style'); st.id='mh3-spin-style'; st.textContent='@keyframes mh3spin{to{transform:rotate(360deg)}}'; document.head.appendChild(st); }
  var ov=document.getElementById('mh3-loading-ov');
  if(!ov){ ov=document.createElement('div'); ov.id='mh3-loading-ov'; ov.style.cssText='position:fixed;inset:0;z-index:10070;background:#0f172a;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;color:#fff;text-align:center;padding:24px;font-family:inherit'; document.body.appendChild(ov); }
  ov.style.display='flex';
  ov.innerHTML='<div style="width:46px;height:46px;border:4px solid rgba(255,255,255,.25);border-top-color:#fff;border-radius:50%;animation:mh3spin 1s linear infinite"></div>'
    +'<div style="font-size:17px;font-weight:700">'+(msg||'Carregando dados do servidor...')+'</div>'
    +'<div style="font-size:13px;color:rgba(255,255,255,.65);max-width:360px;line-height:1.5">O sistema está baixando os dados mais recentes antes de liberar — pra ninguém trabalhar em cima de informação velha.</div>'
    +(comBotoes?'<div style="display:flex;gap:10px;margin-top:10px"><button id="mh3-ld-retry" style="background:#fff;color:#0f172a;border:none;border-radius:8px;padding:11px 20px;font-weight:700;cursor:pointer">Tentar de novo</button><button id="mh3-ld-sair" style="background:transparent;color:#fff;border:1px solid rgba(255,255,255,.4);border-radius:8px;padding:11px 20px;cursor:pointer">Sair</button></div>':'');
}
function _removerOverlayCarregando(){ var ov=document.getElementById('mh3-loading-ov'); if(ov) ov.style.display='none'; }
async function _carregarInicialBloqueante(){
  window._pullInicialOk=false;
  _mostrarOverlayCarregando('Carregando dados do servidor...', false);
  try{ await syncCarregar(); }catch(e){}
  if(window._pullInicialOk){ _removerOverlayCarregando(); return; }
  _mostrarOverlayCarregando('Não consegui carregar os dados do servidor. Verifique a internet.', true);
  var br=document.getElementById('mh3-ld-retry'); if(br) br.onclick=function(){ _carregarInicialBloqueante(); };
  var bs=document.getElementById('mh3-ld-sair'); if(bs) bs.onclick=function(){ try{ fazerLogout(); }catch(e){ location.reload(); } };
}
function entrarSistema(nome, perfil) {
    const ls = document.getElementById('login-screen');
    if (ls) ls.style.display = 'none';
    const sbUn = document.querySelector('.sb-un');
    if (sbUn) sbUn.textContent = nome;
    const sbUr = document.querySelector('.sb-ur');
    if (sbUr) sbUr.textContent = perfil === 'admin' ? 'Administrador' : perfil === 'operacional' ? 'Operacional' : perfil === 'motorista' ? 'Motorista' : perfil;
    const sbAv = document.querySelector('.sb-av');
    if (sbAv) sbAv.textContent = (nome||'U').charAt(0).toUpperCase();
    const niAudit = document.getElementById('ni-audit');
    if (niAudit) niAudit.style.display = perfil === 'admin' ? '' : 'none';
    if(typeof aplicarPermissoes==='function')setTimeout(aplicarPermissoes,100);

  setTimeout(function(){ if(typeof popRelSubmenu==='function')popRelSubmenu(); },180);
  setTimeout(function(){
    try{
      var pm=new URLSearchParams(location.search).get('p');
      if(pm && document.getElementById('pg-'+pm)){ go(pm); }
    }catch(e){}
  }, 240);
  if(typeof iniciarMonitorInatividade==='function')iniciarMonitorInatividade();
}

async function trocarMinhaSenha() {
  const _sn=document.getElementById('senha-nova').value;
  if(_sn.length<8||!/[A-Za-z]/.test(_sn)||!/[0-9]/.test(_sn)){toast('Senha fraca: mínimo 8 caracteres com letra e número','er');return;}
    const nova = document.getElementById('senha-nova').value;
    const conf = document.getElementById('senha-conf').value;
    const msg  = document.getElementById('senha-msg');
    const btn  = document.getElementById('senha-btn');

    function mostrarMsg(texto, cor) {
        msg.style.display = 'block';
        msg.textContent = texto;
        msg.style.background = cor === 'erro' ? '#fee2e2' : '#dcfce7';
        msg.style.color = cor === 'erro' ? '#b91c1c' : '#15803d';
    }

    // Só bloqueia se o login foi LOCAL
    if (!authToken || authToken.indexOf('local_') === 0) {
        mostrarMsg('Sem conexão com o servidor. Saia e entre de novo com internet.', 'erro');
        return;
    }
    if (!nova || !conf) { mostrarMsg('Preencha os dois campos.', 'erro'); return; }
    if (nova.length < 6) { mostrarMsg('A senha precisa ter pelo menos 6 caracteres.', 'erro'); return; }
    if (nova !== conf) { mostrarMsg('As duas senhas não são iguais. Verifique.', 'erro'); return; }

    btn.disabled = true;
    btn.textContent = 'Salvando...';

    try {
        const r = await apiCall('trocar_senha', { nova: nova });
        if (r && r.ok) {
            mostrarMsg('Senha alterada com sucesso! Use a nova senha no próximo login.', 'ok');
            document.getElementById('senha-nova').value = '';
            document.getElementById('senha-conf').value = '';
            setTimeout(() => { closeM('m-senha'); msg.style.display='none'; }, 2500);
        } else {
            mostrarMsg((r && r.msg) ? r.msg : 'Não foi possível alterar agora. Tente mais tarde.', 'erro');
        }
    } catch(e) {
        mostrarMsg('Erro de conexão. Verifique a internet e tente de novo.', 'erro');
    }
    btn.disabled = false;
    btn.textContent = 'Salvar Nova Senha';
}


// ---- LOGOFF AUTOMÁTICO POR INATIVIDADE ----
let _ultimaAtividade=Date.now();
let _inatInterval=null;
function logoffMinConfig(){ return parseInt((D.config&&D.config.logoffMin)||0)||0; }
function marcarAtividade(){ _ultimaAtividade=Date.now(); }
function logoffPorInatividade(){
  try{ if(typeof apiCall==='function')apiCall('logout'); }catch(e){}
  authToken=''; authUser=null;
  localStorage.removeItem('mh3_token'); localStorage.removeItem('mh3_user');
  alert('Sessão encerrada por inatividade ('+logoffMinConfig()+' min sem uso). Faça login novamente.');
  location.reload();
}
function iniciarMonitorInatividade(){
  ['mousemove','mousedown','keydown','scroll','touchstart','click'].forEach(ev=>{
    document.removeEventListener(ev, marcarAtividade);
    document.addEventListener(ev, marcarAtividade, {passive:true});
  });
  marcarAtividade();
  if(_inatInterval) clearInterval(_inatInterval);
  _inatInterval=setInterval(()=>{
    const min=logoffMinConfig();
    if(!min||min<=0) return;
    const ls=document.getElementById('login-screen');
    if(ls && ls.style.display==='flex') return; // não está logado
    if(Date.now()-_ultimaAtividade >= min*60000){
      clearInterval(_inatInterval);
      logoffPorInatividade();
    }
  }, 15000);
}
function salvarLogoffMin(){
  const inp=document.getElementById('cfg-logoff-min');
  const v=parseInt(inp.value)||0;
  if(v<0||v>480){toast('Use de 0 a 480 minutos','er');return;}
  D.config=D.config||{}; D.config.logoffMin=v;
  sv();
  marcarAtividade(); iniciarMonitorInatividade();
  const st=document.getElementById('cfg-logoff-status');
  if(st)st.textContent = v>0 ? ('✅ Ativo: desconecta após '+v+' min sem uso.') : '⚪ Desativado.';
  toast(v>0?('Logoff automático: '+v+' min'):'Logoff automático desativado','ok');
}

async function fazerLogout() {
    if (!confirm('Deseja sair do sistema?')) return;
    await apiCall('logout');
    authToken = '';
    authUser  = null;
    localStorage.removeItem('mh3_token');
    localStorage.removeItem('mh3_user');
    location.reload();
}

// ---- AUTO-SYNC: puxa dados de todos automaticamente (a cada 45s) ----
let _autoSyncTimer=null;
function _avisarServidorVelho(){
  if(document.getElementById('aviso-sv-velho'))return;
  var d=document.createElement('div');
  d.id='aviso-sv-velho';
  d.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99999;background:#dc2626;color:#fff;padding:10px 14px;text-align:center;font-size:13px;font-weight:600;box-shadow:0 2px 10px rgba(0,0,0,.35)';
  d.innerHTML='\u26a0\ufe0f O arquivo <b>api.php</b> do servidor est\u00e1 DESATUALIZADO. A auditoria e a atualiza\u00e7\u00e3o entre usu\u00e1rios s\u00f3 voltam a funcionar quando voc\u00ea subir o <b>api.php</b> novo (junto com o index.php). &nbsp;<span style="text-decoration:underline;cursor:pointer" onclick="document.getElementById(\'aviso-sv-velho\').remove()">fechar</span>';
  document.body.appendChild(d);
}
function _ocultarAvisoServidorVelho(){var d=document.getElementById('aviso-sv-velho');if(d)d.remove();}

function iniciarAutoSync(){
  if(_autoSyncTimer) return; // já está rodando
  // Verificação LEVE a cada 20s: só puxa tudo se algo mudou no servidor (alivia o banco com vários usuários)
  _autoSyncTimer=setInterval(_verificarMudancaServidor, 20000);
  // Pull completo de segurança a cada 3 min
  if(!window._autoSyncFullTimer) window._autoSyncFullTimer=setInterval(_autoSyncPull, 180000);
  // Quando a aba volta a ficar visível, faz uma verificação na hora (sem ficar consultando em segundo plano)
  try{
    if(typeof document!=='undefined' && !window._visSyncBound){
      window._visSyncBound=true;
      document.addEventListener('visibilitychange', function(){
        if(!document.hidden){ try{ if(typeof syncAtivo!=='undefined' && syncAtivo && authToken) _verificarMudancaServidor(); }catch(e){} }
      });
    }
  }catch(e){}
  // Backup automático no servidor (1x/dia, quando o sistema é usado)
  setTimeout(function(){ try{ _autoBackupServidorSeNecessario(); }catch(e){} }, 8000);
}
var _falhasSyncSeguidas=0;
function _registrarSucessoSync(){ _falhasSyncSeguidas=0; }
function _registrarFalhaSync(){
  _falhasSyncSeguidas++;
  if(_falhasSyncSeguidas>=3 && !window._reconectandoSessao) _mostrarReconexaoSessao();
}
function _mostrarReconexaoSessao(){
  if(window._reconectandoSessao) return;
  window._reconectandoSessao=true;
  if(typeof _mostrarOverlayCarregando==='function') _mostrarOverlayCarregando('Conexão com o servidor perdida — reconectando...', true);
  var bs=document.getElementById('mh3-ld-sair'); if(bs){ bs.textContent='Entrar de novo'; bs.onclick=function(){ try{ authToken=''; authUser=null; localStorage.removeItem('mh3_token'); localStorage.removeItem('mh3_user'); }catch(e){} location.reload(); }; }
  var br=document.getElementById('mh3-ld-retry'); if(br){ br.textContent='Tentar agora'; br.onclick=function(){ _loopReconexao(); }; }
  _loopReconexao();
}
function _loopReconexao(){
  if(!window._reconectandoSessao) return;
  Promise.resolve().then(function(){ return apiCall('ultima_alteracao'); }).then(function(r){
    if(r && r.ok){
      window._reconectandoSessao=false; _falhasSyncSeguidas=0;
      if(typeof _removerOverlayCarregando==='function') _removerOverlayCarregando();
      try{ if(typeof _autoSyncPull==='function') _autoSyncPull(); }catch(e){}
    } else if(window._reconectandoSessao){ setTimeout(_loopReconexao, 5000); }
  }).catch(function(){ if(window._reconectandoSessao){ setTimeout(_loopReconexao, 5000); } });
}
async function _verificarMudancaServidor(){
  try{
    if(!(typeof syncAtivo!=='undefined' && syncAtivo)) return;
    if(!authToken || String(authToken).indexOf('local_')===0) return;
    if(_editandoAgora()) return;
    if(typeof document!=='undefined' && document.hidden) return; // aba em segundo plano: não consulta o banco
    var r=null;
    try{ r = await apiCall('ultima_alteracao'); }catch(e){ r=null; }
    if(!r || !r.ok){ _registrarFalhaSync(); return; }
    _registrarSucessoSync();
    if(!r.mods){ if(typeof _avisarServidorVelho==='function')_avisarServidorVelho(); return; }
    if(typeof _ocultarAvisoServidorVelho==='function')_ocultarAvisoServidorVelho();
    var atuais = r.mods;
    // primeira leitura: só guarda a referência
    if(!window._verMods){ window._verMods = atuais; return; }
    // se EU mesmo acabei de salvar, atualizo a referência e NÃO puxo (evita re-render à toa)
    if(window._localSaveTs && (Date.now()-window._localSaveTs < 5000)){ window._verMods = atuais; return; }
    // descobre quais módulos mudaram
    var mudaram=[];
    for(var m in atuais){ if(!Object.prototype.hasOwnProperty.call(atuais,m))continue; if(atuais[m]!==window._verMods[m]) mudaram.push(m); }
    window._verMods = atuais;
    if(mudaram.length){ await _pullModulos(mudaram); }
  }catch(e){}
}
async function _pullModulos(mods){
  try{
    for(var i=0;i<mods.length;i++){
      var mod=mods[i];
      try{ var r=await apiCall('buscar&modulo='+encodeURIComponent(mod)); if(r && r.ok && Array.isArray(r.dados)){ D[mod]=r.dados; } }catch(e){}
    }
    try{_capturarSids();}catch(e){}
    try{localStorage.setItem('mh3v5', JSON.stringify(D));}catch(e){}
    if(_editandoAgora()) return; // abriu algo enquanto buscava
    try{ if(typeof cur!=='undefined' && typeof rp==='function') rp(cur); }catch(e){}
  }catch(e){}
}
function _editandoAgora(){
  if(document.querySelector('.mo.op')) return true; // modal aberto
  var ae=document.activeElement;
  if(ae && (ae.tagName==='INPUT'||ae.tagName==='TEXTAREA'||ae.tagName==='SELECT')) return true; // digitando
  return false;
}
async function _autoSyncPull(){
  try{
    if(!(typeof syncAtivo!=='undefined' && syncAtivo)) return;          // só online
    if(!authToken || String(authToken).indexOf('local_')===0) return;
    if(_editandoAgora()) return;                                         // não interrompe edição
    if(typeof document!=='undefined' && document.hidden) return;         // aba em segundo plano: não busca tudo
    const controller=new AbortController();
    const tid=setTimeout(function(){controller.abort();},30000);
    const res=await fetch('api.php?action=buscar_tudo&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:'{}',signal:controller.signal});
    clearTimeout(tid);
    const r=await res.json();
    if(r && r.ok && r.dados){
      ['equips','contratos','medicoes','manutencoes','vendas','despesas','estoque','nfs','revisoes','checklists','usuarios','funcionarios','clientes','pneus','mobilizacoes','saidasMaterial','ajudasMotorista','contasBanco','investimentos','tratativas','pneus_pend','seguros'].forEach(function(mod){ if(r.dados[mod]) D[mod]=r.dados[mod]; });
      try{_syncMergeExtra(r.dados);}catch(e){}
      try{_capturarSids();}catch(e){}
      try{localStorage.setItem('mh3v5', JSON.stringify(D));}catch(e){}
      if(_editandoAgora()) return;                                       // abriu algo enquanto buscava
      try{ if(typeof cur!=='undefined' && typeof rp==='function') rp(cur); }catch(e){}
    }
  }catch(e){}
}

// ---- SYNC CARREGAR ----
async function syncCarregar() {
    // Inicia o sistema imediatamente — sem loading bloqueante
    _initCore();
    try{iniciarAutoSync();}catch(e){}

    // Sincroniza com banco em background (sem bloquear)
    try {
        const controller = new AbortController();
        setTimeout(() => controller.abort(), 45000);

        const res = await fetch('api.php?action=buscar_tudo&token=' + encodeURIComponent(authToken), {
            method: 'POST',
            headers: {'Content-Type':'application/json', 'X-Token': authToken},
            body: '{}',
            signal: controller.signal
        });

        const r = await res.json();

        if (r.ok && r.dados) {
            ['equips','contratos','medicoes','manutencoes','vendas','despesas',
             'estoque','nfs','revisoes','checklists','usuarios','funcionarios','clientes','pneus','mobilizacoes','saidasMaterial','ajudasMotorista','contasBanco','investimentos','tratativas','pneus_pend','seguros'].forEach(mod => {
                if (r.dados[mod]) D[mod] = r.dados[mod];
            }); try{_syncMergeExtra(r.dados);}catch(e){} try{_capturarSids();}catch(e){}
            try{normalizarUsuarios();}catch(e){}
            try{localStorage.setItem('mh3_ultima_sync', String(Date.now()));}catch(e){}
            mostrarStatusConexao(true);
            rp(cur);

            try {
                const cf = await fetch('api.php?action=buscar_config&token=' + encodeURIComponent(authToken), {
                    method:'POST',
                    headers:{'Content-Type':'application/json', 'X-Token': authToken},
                    body:'{}'
                });
                const cfg = await cf.json();
                if (cfg.ok && cfg.config) D.config = {...D.config, ...cfg.config};
                // Restaura usuários vindos das configurações (cross-PC)
                if (D.config && D.config.usuarios && D.config.usuarios.length) {
                    D.usuarios = D.config.usuarios;
                    try{ localStorage.setItem('mh3v5', JSON.stringify(D)); }catch(e){}
                }
            } catch(e) {}
        } else if (r.msg === 'sessao' || res.status === 401) {
            // Token realmente recusado pelo servidor
            syncAtivo = false;
            mostrarStatusConexao(false);
        } else {
            // Banco respondeu (mesmo vazio) — conexão OK, mantém sync ativo
            mostrarStatusConexao(true);
        }
    } catch(e) {
        // Erro de rede/timeout no carregamento. Se o login foi pelo SERVIDOR (token real),
        // a conexão está OK — mantém ONLINE (a sincronização tenta de novo ao salvar).
        if (authToken && authToken.indexOf('local_') === 0) { syncAtivo = false; mostrarStatusConexao(false); }
        else { mostrarStatusConexao(true); }
    }
}


// ---- BOTÃO: ATUALIZAR / RECARREGAR DADOS DO SERVIDOR (manual) ----
window.recarregarDados = async function(){
  if(!authToken){ toast('Faça login primeiro.','er'); return; }
  if(String(authToken).indexOf('local_')===0){ toast('Você entrou em modo LOCAL (offline). Saia e entre de novo com internet para puxar os dados do servidor.','er'); mostrarStatusConexao(false); return; }
  toast('🔄 Buscando dados do servidor...');
  var r=null, status=0, ultErro='';
  for(var tent=1; tent<=3; tent++){
    try{
      const controller=new AbortController();
      const tid=setTimeout(function(){controller.abort();},45000);
      const res=await fetch('api.php?action=buscar_tudo&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:'{}',signal:controller.signal});
      clearTimeout(tid); status=res.status;
      var _txt=await res.text();
      try{ r=JSON.parse(_txt); }catch(pe){ r=null; ultErro='resposta vazia ou cortada (HTTP '+status+')'; }
      if(r && r.erro_servidor){ ultErro=r.erro_servidor; }
      if(r && r.ok) break;
      if((r && r.msg==='sessao') || status===401){ break; }
    }catch(e){ r=null; ultErro=(e&&(e.message||e.name))||'rede'; }
    if(tent<3){ await new Promise(function(ok){ setTimeout(ok, 1500*tent); }); }
  }
  if(r && r.ok && r.dados){
    ['equips','contratos','medicoes','manutencoes','vendas','despesas','estoque','nfs','revisoes','checklists','usuarios','funcionarios','clientes','pneus','mobilizacoes','saidasMaterial','ajudasMotorista','contasBanco','investimentos','tratativas','pneus_pend','seguros'].forEach(function(mod){ if(r.dados[mod]) D[mod]=r.dados[mod]; }); try{_syncMergeExtra(r.dados);}catch(e){} try{_capturarSids();}catch(e){}
    try{normalizarUsuarios();}catch(e){}
    try{
      const cf=await fetch('api.php?action=buscar_config&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:'{}'});
      const cfg=await cf.json();
      if(cfg.ok && cfg.config) D.config=Object.assign({},D.config,cfg.config);
      if(D.config && D.config.usuarios && D.config.usuarios.length) D.usuarios=D.config.usuarios;
    }catch(e){}
    try{ localStorage.setItem('mh3v5', JSON.stringify(D)); }catch(e){}
    try{ localStorage.setItem('mh3_ultima_sync', String(Date.now())); }catch(e){}
    mostrarStatusConexao(true);
    rp(cur);
    toast('✅ Dados atualizados do servidor!','ok');
  } else if((r && r.msg==='sessao') || status===401){
    toast('Sua sessão expirou. Saia e entre novamente.','er');
    mostrarStatusConexao(false);
  } else if(ultErro){
    mostrarStatusConexao(true);
    toast('O servidor teve um problema ao enviar os dados: '+ultErro+'. Seus dados locais estão seguros — o sistema tenta de novo sozinho.','er');
  } else {
    mostrarStatusConexao(true);
    toast('Não consegui atualizar agora (tentei 3 vezes). Seus dados locais estão seguros — o sistema continua tentando sozinho.','er');
  }
};

function _syncMergeExtra(dados){if(!dados)return;['propostas','pneus_hist'].forEach(function(mod){var srv=dados[mod];if(srv&&srv.length>0){D[mod]=srv;}else if(srv&&(!D[mod]||D[mod].length===0)){D[mod]=srv;}});}
// Memoriza os IDs que vieram do servidor, por módulo. Serve para o salvamento
// saber o que foi REALMENTE excluído pelo usuário (e não apagar o resto).
function _capturarSids(){
  try{
    window._sidsServer = window._sidsServer || {};
    window._modJson = window._modJson || {};
    window._recJson = window._recJson || {};
    ['equips','contratos','medicoes','manutencoes','vendas','despesas','estoque','nfs','revisoes','checklists','usuarios','funcionarios','clientes','pneus','mobilizacoes','saidasMaterial','ajudasMotorista','contasBanco','investimentos','tratativas','pneus_pend','seguros','propostas'].forEach(function(m){
      var _l = D[m]||[];
      window._sidsServer[m] = _l.map(function(r){return r&&r.id;}).filter(function(x){return x!==undefined&&x!==null&&x!=='';});
      try{ window._modJson[m] = JSON.stringify(_l); }catch(e){}
      var _mp={};
      for(var _i=0;_i<_l.length;_i++){ var _r=_l[_i]; if(!_r) continue; var _id=_r.id; if(_id===undefined||_id===null||_id==='')continue; try{ _mp[_id]=JSON.stringify(_r); }catch(e){ _mp[_id]=''; } }
      window._recJson[m]=_mp;
    });
    window._pullInicialOk = true; // ja baixou e memorizou o estado do servidor: agora pode enviar com seguranca
  }catch(e){}
}
async function syncSalvar(modulo, lista, excluir) {
    if (!syncAtivo) return;
    async function _tentar(){
        const _r = await fetch('api.php?action=salvar&token=' + encodeURIComponent(authToken), {
            method:'POST', headers:{'Content-Type':'application/json', 'X-Token': authToken},
            body: JSON.stringify({modulo, dados:lista, excluir: excluir||[]})
        });
        let _ok = !!(_r && _r.ok);
        if (_ok) { try { const _j = await _r.clone().json(); if (_j && _j.ok === false) _ok = false; } catch(_e){} }
        return _ok;
    }
    var ok=false;
    try{ ok = await _tentar(); }catch(e){ ok=false; }
    if(!ok){ // tenta de novo uma vez (evita falso alarme em rede instável / vários usuários)
        await new Promise(function(r){setTimeout(r,800);});
        try{ ok = await _tentar(); }catch(e){ ok=false; }
    }
    if(ok){ window._falhasServidor = 0; }
    else {
        window._falhasServidor = (window._falhasServidor||0) + 1;
        _logSyncErro('salvar '+modulo, 'não confirmou a gravação');
        if(window._falhasServidor >= 3) _avisarFalhaSalvar('servidor', {modulo:modulo}); // só avisa em falha persistente
    }
}



function mostrarStatusConexao(online) {
    let el = document.getElementById('conn-status');
    if (!el) {
        el = document.createElement('div');
        el.id = 'conn-status';
        el.style.cssText = 'position:fixed;bottom:16px;left:16px;font-size:10px;padding:4px 10px;border-radius:20px;z-index:1000;font-family:\'Barlow\',sans-serif;font-weight:600;';
        document.body.appendChild(el);
    }
    // Selo destacado ao lado do nome do usuário
    const badge = document.getElementById('sb-online');
    if (badge) {
        if (online) {
            badge.textContent = '● ONLINE';
            badge.style.background='rgba(34,197,94,.18)'; badge.style.color='#16a34a'; badge.style.border='1px solid rgba(34,197,94,.4)';
        } else {
            badge.textContent = '● OFFLINE';
            badge.style.background='rgba(245,158,11,.18)'; badge.style.color='#d97706'; badge.style.border='1px solid rgba(245,158,11,.35)';
        }
    }
    if (online) {
        el.style.cssText += 'background:rgba(34,197,94,.15);border:1px solid rgba(34,197,94,.3);color:#22c55e;';
        el.textContent = '● Online — MySQL';
    } else {
        el.style.cssText += 'background:rgba(245,158,11,.15);border:1px solid rgba(245,158,11,.3);color:#f59e0b;';
        el.textContent = '● Offline — Local';
    }
}

