// ============ BACKUP & SEGURANÇA ============

// Backup completo dos dados em JSON
function fazerBackup() {
    try {
        const backup = {
            versao: 'MH3 v6',
            gerado_em: new Date().toISOString(),
            empresa: 'MH3 Rental Ltda',
            dados: {
                equips:       D.equips,
                contratos:    D.contratos,
                medicoes:     D.medicoes,
                manutencoes:  D.manutencoes,
                vendas:       D.vendas,
                despesas:     D.despesas,
                estoque:      D.estoque,
                nfs:          D.nfs,
                revisoes:     D.revisoes||[],
                checklists:   D.checklists,
                usuarios:     D.usuarios,
                config:       D.config
            },
            totais: {
                equipamentos: D.equips.length,
                contratos:    D.contratos.length,
                medicoes:     D.medicoes.length,
                manutencoes:  D.manutencoes.length,
                vendas:       D.vendas.length,
                despesas:     D.despesas.length,
                estoque:      D.estoque.length,
                nfs:          D.nfs.length
            }
        };
        const json    = JSON.stringify(backup, null, 2);
        const blob    = new Blob([json], {type:'application/json'});
        const url     = URL.createObjectURL(blob);
        const data    = new Date().toISOString().slice(0,10);
        const a       = document.createElement('a');
        a.href        = url;
        a.download    = `MH3_Backup_${data}.json`;
        a.click();
        URL.revokeObjectURL(url);
        toast(`✓ Backup gerado — ${Object.values(backup.totais).reduce((s,v)=>s+v,0)} registros salvos`,'ok');
        // Loga o backup
        if(syncAtivo) apiCall('log_action',{acao:'BACKUP_GERADO',modulo:'sistema'});
    } catch(e) {
        toast('Erro ao gerar backup: '+e.message,'er');
    }
}

// Restaurar backup de arquivo JSON
function restaurarBackup() {
    if(!confirm('⚠️ ATENÇÃO\n\nRestaurar um backup irá SUBSTITUIR todos os dados atuais.\n\nDeseja continuar?')) return;
    const input = document.createElement('input');
    input.type  = 'file';
    input.accept= '.json';
    input.onchange = async (e) => {
        const file   = e.target.files[0];
        if(!file) return;
        const reader = new FileReader();
        reader.onload = async (ev) => {
            try {
                const backup = JSON.parse(ev.target.result);
                if(!backup.dados) { toast('Arquivo inválido — não é um backup MH3','er'); return; }
                const d = backup.dados;
                if(d.equips)      D.equips      = d.equips;
                if(d.contratos)   D.contratos   = d.contratos;
                if(d.medicoes)    D.medicoes    = d.medicoes;
                if(d.manutencoes) D.manutencoes = d.manutencoes;
                if(d.vendas)      D.vendas      = d.vendas;
                if(d.despesas)    D.despesas    = d.despesas;
                if(d.estoque)     D.estoque     = d.estoque;
                if(d.nfs)         D.nfs         = d.nfs;
                if(d.revisoes)    D.revisoes    = d.revisoes;
                if(d.checklists)  D.checklists  = d.checklists;
                if(d.config)      D.config      = {...D.config,...d.config};
                sv();
                toast(`✓ Backup restaurado de ${backup.gerado_em?.slice(0,10)||'?'}`,'ok');
                setTimeout(()=>location.reload(),1500);
            } catch(err) {
                toast('Arquivo corrompido ou inválido','er');
            }
        };
        reader.readAsText(file);
    };
    input.click();
}

// ============ ATUALIZAÇÃO INCREMENTAL (não perde dados) ============
// Sobrescreve sv() para usar UPSERT em vez de apagar e recriar
async function syncSalvarIncremental(modulo, lista) {
    if (!syncAtivo || !authToken) return;
    // Envia cada item individualmente com UPSERT
    for (const item of lista) {
        await apiCall('upsert', {modulo, item});
    }
}

// Backup automático a cada 2 horas em localStorage
function getBackupCfg(){
  if(!D.config.backup) D.config.backup={intervaloDias:1, horario:'23:00', ativo:true};
  return D.config.backup;
}
function agendarBackupAuto() {
    // Backup SEMPRE ao logar (qualquer usuário, qualquer dia/hora)
    fazerBackupAuto();
    // Durante a sessão: também faz no horário/intervalo configurado (caso fique aberto)
    setInterval(()=>verificarBackupAgendado(false), 5 * 60 * 1000);
}
function diasDesdeUltimoBackup(){
    const ultimo=localStorage.getItem('mh3_ultimo_backup_auto');
    if(!ultimo) return 9999; // nunca fez
    return (new Date()-new Date(ultimo))/(1000*60*60*24);
}
function verificarBackupAgendado(aoAbrir){
    const cfg=getBackupCfg();
    if(!cfg.ativo) return;
    const intervalo=cfg.intervaloDias||1;
    const dias=diasDesdeUltimoBackup();
    // Já cumpriu o intervalo? (ainda não está na hora de novo backup)
    if(dias < intervalo) return;
    const agora=new Date();
    const [h,m]=(cfg.horario||'23:00').split(':').map(Number);
    const passouHorario = agora.getHours()>h || (agora.getHours()===h && agora.getMinutes()>=m);
    // CATCH-UP: ao abrir o sistema, se está devendo backup (passou o intervalo)
    //   e já passou o horário de hoje OU está MUITO atrasado (mais de 1 dia além do intervalo),
    //   faz o backup atrasado na hora — não importa que horas são.
    if(aoAbrir){
        if(passouHorario || dias >= intervalo + 0.5){
            fazerBackupAuto();
        }
        return;
    }
    // Durante a sessão: só faz quando passar do horário configurado
    if(passouHorario) fazerBackupAuto();
}

function fazerBackupAuto() {
    try {
        const _leve = (typeof _dadosLeves==='function') ? _dadosLeves() : D;
        const snap = {ts: new Date().toISOString(), dados: _leve};
        // Mantém o último backup (leve, sem fotos/arquivos pesados)
        localStorage.setItem('mh3_autobackup', JSON.stringify(snap));
        // Mantém histórico dos últimos 2 backups (leves)
        let hist = [];
        try { hist = JSON.parse(localStorage.getItem('mh3_backup_hist')||'[]'); } catch(e){}
        hist.unshift({ts: snap.ts, dados: snap.dados});
        hist = hist.slice(0, 2);
        localStorage.setItem('mh3_backup_hist', JSON.stringify(hist));
        localStorage.setItem('mh3_ultimo_backup_auto', new Date().toISOString());
        console.log('[MH3] Auto-backup salvo:', new Date().toLocaleTimeString('pt-BR'));
    } catch(e) { console.warn('[MH3] Falha no backup:', e); }
}

function listarBackups() {
    try {
        const hist = JSON.parse(localStorage.getItem('mh3_backup_hist')||'[]');
        return hist;
    } catch(e) { return []; }
}

function restaurarBackupHist(idx) {
    const hist = listarBackups();
    if (!hist[idx]) { toast('Backup não encontrado','er'); return; }
    if (!confirm('Restaurar este backup? Os dados atuais serão substituídos.\n\nRecomendo fazer um backup atual antes.')) return;
    D = hist[idx].dados;
    sv();
    toast('Backup restaurado! Recarregando...','ok');
    setTimeout(()=>location.reload(), 1500);
}

// ===== Backup no SERVIDOR (banco de dados) =====
function _ehAdminBkp(){ try{ return !!(typeof authUser!=='undefined' && authUser && (authUser.perfil==='admin' || ((authUser.nome||'').toLowerCase().indexOf('noninho')>=0) || ((authUser.login||'').toLowerCase().indexOf('noninho')>=0))); }catch(e){ return false; } }
function _onlineBkp(){ return (typeof syncAtivo!=='undefined' && syncAtivo) && (typeof authToken!=='undefined' && authToken) && String(authToken||'').indexOf('local_')!==0; }
function _snapshotBackupServidor(){
  var dados = (typeof _dadosLeves==='function') ? _dadosLeves() : D;
  return { versao:(window.APP_BUILD||'MH3'), gerado_em:new Date().toISOString(), empresa:'MH3 Rental Ltda', origem:'servidor', dados:dados };
}
async function backupServidorAgora(silencioso){
  if(!_onlineBkp()){ if(!silencioso) toast('Backup no servidor só funciona online.','er'); return false; }
  try{
    var conteudo = JSON.stringify(_snapshotBackupServidor());
    var r = await fetch('api.php?action=backup_salvar&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:JSON.stringify({conteudo:conteudo, app_versao:(window.APP_BUILD||'')})});
    var j = await r.json();
    if(j && j.ok){
      try{ localStorage.setItem('mh3_ultimo_backup_srv', String(Date.now())); }catch(e){}
      if(!silencioso) toast('☁️ Backup salvo no servidor (#'+j.id+').','ok');
      try{ listarBackupsServidor(); }catch(e){}
      return true;
    }
    if(!silencioso) toast('Não consegui salvar o backup no servidor.','er');
    return false;
  }catch(e){ if(!silencioso) toast('Erro no backup do servidor: '+((e&&e.message)||e),'er'); return false; }
}
async function _autoBackupServidorSeNecessario(){
  try{
    if(!_onlineBkp()) return;
    var r = await fetch('api.php?action=backup_listar&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:'{}'});
    var j = await r.json();
    if(!(j && j.ok)) return;
    var lista = j.lista || [];
    var precisa = true;
    if(lista.length){
      var t = Date.parse(String(lista[0].criado_em||'').replace(' ','T'));
      if(!isNaN(t) && (Date.now()-t) < 20*3600*1000) precisa=false;
    }
    if(precisa){ await backupServidorAgora(true); }
  }catch(e){}
}
function _fmtDataHoraBkp(s){ try{ var t=Date.parse(String(s||'').replace(' ','T')); if(isNaN(t)) return String(s||'-'); var d=new Date(t); return d.toLocaleDateString('pt-BR')+' '+d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}); }catch(e){ return String(s||'-'); } }
function _fmtTamBkp(n){ n=parseInt(n)||0; if(n<1024) return n+' B'; if(n<1048576) return (n/1024).toFixed(0)+' KB'; return (n/1048576).toFixed(1)+' MB'; }
async function listarBackupsServidor(){
  var cont = document.getElementById('bkp-srv-lista');
  if(!cont) return;
  if(!_onlineBkp()){ cont.innerHTML='<div style="color:var(--mt)">Disponível somente online.</div>'; return; }
  cont.innerHTML='<div style="color:var(--mt)">Carregando backups do servidor...</div>';
  try{
    var r = await fetch('api.php?action=backup_listar&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:'{}'});
    var j = await r.json();
    if(!(j && j.ok)){ cont.innerHTML='<div style="color:#c00">Não consegui listar os backups do servidor.</div>'; return; }
    var lista = j.lista || [];
    if(!lista.length){ cont.innerHTML='<div style="color:var(--mt)">Nenhum backup no servidor ainda. Clique no botão acima.</div>'; return; }
    var adm = _ehAdminBkp();
    var html='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr style="text-align:left;color:var(--mt);font-size:11px"><th style="padding:5px 6px">Data / Hora</th><th>Origem</th><th>Tamanho</th><th></th></tr></thead><tbody>';
    for(var i=0;i<lista.length;i++){
      var b=lista[i];
      html+='<tr style="border-top:1px solid rgba(120,120,120,.2)"><td style="padding:5px 6px;white-space:nowrap">'+escH(_fmtDataHoraBkp(b.criado_em))+'</td><td>'+escH(b.origem||'-')+'</td><td style="white-space:nowrap">'+_fmtTamBkp(b.tamanho)+'</td><td style="white-space:nowrap;text-align:right">';
      html+='<button class="btn bg btn-xs" onclick="baixarBackupServidor('+b.id+')" title="Baixar este backup">⬇️</button> ';
      if(adm){
        html+='<button class="btn bw btn-xs" onclick="restaurarBackupServidor('+b.id+')" title="Restaurar este backup">↩️</button> ';
        html+='<button class="btn bd btn-xs" onclick="apagarBackupServidor('+b.id+')" title="Apagar este backup">🗑️</button>';
      }
      html+='</td></tr>';
    }
    html+='</tbody></table></div>';
    cont.innerHTML=html;
  }catch(e){ cont.innerHTML='<div style="color:#c00">Erro ao listar: '+escH((e&&e.message)||'')+'</div>'; }
}
async function baixarBackupServidor(id){
  try{
    var r = await fetch('api.php?action=backup_obter&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:JSON.stringify({id:id})});
    var j = await r.json();
    if(!(j && j.ok && j.conteudo)){ toast('Não consegui obter o backup.','er'); return; }
    var blob=new Blob([j.conteudo],{type:'application/json'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a'); var dt=String(j.criado_em||'').replace(/[^0-9]/g,'').slice(0,12);
    a.href=url; a.download='MH3_BackupServidor_'+(dt||id)+'.json'; a.click();
    URL.revokeObjectURL(url);
    toast('⬇️ Backup baixado.','ok');
  }catch(e){ toast('Erro ao baixar: '+((e&&e.message)||e),'er'); }
}
function restaurarBackupServidor(id){
  if(!_ehAdminBkp()){ toast('Restaurar é restrito ao administrador.','er'); return; }
  reqSenha(function(){
    if(!confirm('⚠️ ATENÇÃO\n\nRestaurar este backup vai SUBSTITUIR todos os dados atuais pelos dados do backup.\n\nFaça um backup agora antes, por segurança. Deseja continuar?')) return;
    (async function(){
      try{
        var r = await fetch('api.php?action=backup_obter&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:JSON.stringify({id:id})});
        var j = await r.json();
        if(!(j && j.ok && j.conteudo)){ toast('Não consegui obter o backup.','er'); return; }
        var bkp = JSON.parse(j.conteudo);
        var d = (bkp && bkp.dados) ? bkp.dados : bkp;
        ['equips','contratos','medicoes','manutencoes','vendas','despesas','estoque','nfs','revisoes','checklists','usuarios','funcionarios','clientes','pneus','mobilizacoes','saidasMaterial','ajudasMotorista','contasBanco','investimentos','tratativas','pneus_pend','seguros','propostas','pneus_hist'].forEach(function(m){ if(d[m]!==undefined) D[m]=d[m]; });
        if(d.config) D.config=Object.assign({},D.config,d.config);
        try{_capturarSids();}catch(e){}
        sv();
        toast('✓ Backup restaurado! Recarregando...','ok');
        setTimeout(function(){ location.reload(); }, 1500);
      }catch(e){ toast('Erro ao restaurar: '+((e&&e.message)||e),'er'); }
    })();
  });
}
function apagarBackupServidor(id){
  if(!_ehAdminBkp()){ toast('Apagar é restrito ao administrador.','er'); return; }
  if(!confirm('Apagar o backup #'+id+' do servidor? Esta ação não tem volta.')) return;
  (async function(){
    try{
      var r = await fetch('api.php?action=backup_apagar&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:JSON.stringify({id:id})});
      var j = await r.json();
      if(j && j.ok){ toast('Backup apagado.','ok'); listarBackupsServidor(); }
      else toast('Não consegui apagar.','er');
    }catch(e){ toast('Erro ao apagar: '+((e&&e.message)||e),'er'); }
  })();
}


// Verificar integridade dos dados
function verificarIntegridade() {
    const problemas = [];
    // Contratos sem equipamento válido
    D.contratos.forEach(c => {
        if(c.eqId && !D.equips.find(e=>e.id===c.eqId))
            problemas.push(`Contrato de ${c.cl} com veículo/equipamento não encontrado`);
    });
    // Medições sem contrato válido
    D.medicoes.forEach(m => {
        if(m.ctId && !D.contratos.find(c=>c.id===m.ctId))
            problemas.push(`Medição de ${m.cl} sem contrato vinculado`);
    });
    // OS sem equipamento válido
    D.manutencoes.forEach(m => {
        if(m.eqId && !D.equips.find(e=>e.id===m.eqId))
            problemas.push(`OS ${m.osNum||''} com veículo/equipamento não encontrado`);
    });
    if(problemas.length) {
        console.warn('[MH3] Problemas de integridade:', problemas);
        toast(`⚠️ ${problemas.length} inconsistência(s) encontrada(s) — verifique o console`,'er');
    }
    return problemas;
}

