function enviarEmailCR(id,tipo){ var rec=(tipo==='med'?D.medicoes:D.vendas).find(function(x){return x.id===id;}); if(!rec){toast('Registro não encontrado','er');return;} window.abrirEnvioEmailLanc(tipo==='med'?'medicao':'venda', rec); }
function enviarEmailCP(id,tipo){ var rec=(tipo==='NF'?D.nfs:D.despesas).find(function(x){return x.id===id;}); if(!rec){toast('Registro não encontrado','er');return;} window.abrirEnvioEmailLanc('conta_pagar', rec); }
function enviarEmailOS(id){ var rec=(D.manutencoes||[]).find(function(x){return x.id===id;}); if(!rec){toast('OS não encontrada','er');return;} window.abrirEnvioEmailLanc('os', rec); }
function verContaLanc(id,tipo){
if(tipo==='NF') return verNf(id);
if(tipo==='Despesa') return verDesp(id);
if(tipo==='med') return verMed(id);
if(tipo==='venda') return verVenda(id);
}
function _achaLanc(id, ctx){
var arr=null, vf='vl';
if(ctx==='NF'){ arr=D.nfs; vf='vl'; }
else if(ctx==='Despesa'){ arr=D.despesas; vf='vl'; }
else if(ctx==='med'){ arr=D.medicoes; vf='total'; }
else if(ctx==='venda'){ arr=D.vendas; vf='total'; }
if(!arr) return null;
var obj=arr.find(function(x){ return x.id===id; });
if(!obj) return null;
var nome=obj.desc||obj.cl||obj.cli||obj.forn||'Lançamento';
return { obj:obj, arr:arr, vf:vf, nome:nome };
}
function abrirAlterarLanc(id, ctx){
var r=_achaLanc(id, ctx);
if(!r){ if(typeof toast==='function') toast('Lançamento não encontrado','er'); return; }
var valAtual=parseFloat(r.obj[r.vf]||0)||0;
var vcAtual=r.obj.vc||'';
window._altLancCtx={ id:id, ctx:ctx };
var ov=document.getElementById('mh3-alt-lanc'); if(ov) ov.remove();
ov=document.createElement('div');
ov.id='mh3-alt-lanc';
ov.style.cssText='position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:16px;';
var nomeSafe=(r.nome||'').replace(/</g,'&lt;');
ov.innerHTML=`<div style="background:var(--cd,#fff);color:var(--tx,#1e293b);border-radius:12px;max-width:420px;width:100%;padding:18px;box-shadow:0 10px 40px rgba(0,0,0,.4);font-family:sans-serif">
<div style="font-size:16px;font-weight:800;margin-bottom:3px">✏️ Alterar lançamento</div>
<div style="font-size:12px;color:var(--mt,#64748b);margin-bottom:14px">${nomeSafe}</div>
<label style="font-size:11px;font-weight:700;color:var(--mt,#64748b)">Valor (R$)</label>
<input id="alt-lanc-valor" type="number" step="0.01" value="${valAtual}" style="width:100%;padding:9px;margin:3px 0 12px;border:1px solid var(--br,#e2e8f0);border-radius:7px;font-size:14px;color:var(--tx,#1e293b);background:var(--cd2,#f8fafc)">
<label style="font-size:11px;font-weight:700;color:var(--mt,#64748b)">Vencimento</label>
<input id="alt-lanc-vc" type="date" value="${vcAtual}" style="width:100%;padding:9px;margin:3px 0 12px;border:1px solid var(--br,#e2e8f0);border-radius:7px;font-size:14px;color:var(--tx,#1e293b);background:var(--cd2,#f8fafc)">
<label style="font-size:11px;font-weight:700;color:var(--mt,#64748b)">Justificativa (obrigatória)</label>
<textarea id="alt-lanc-just" placeholder="Por que está alterando?" style="width:100%;min-height:60px;padding:9px;margin:3px 0 14px;border:1px solid var(--br,#e2e8f0);border-radius:7px;font-size:13px;color:var(--tx,#1e293b);background:var(--cd2,#f8fafc)"></textarea>
<label style="font-size:11px;font-weight:700;color:var(--mt,#64748b)">Sua senha (de quem está editando)</label>
<input id="alt-lanc-senha" type="password" placeholder="sua senha de acesso" style="width:100%;padding:9px;margin:3px 0 14px;border:1px solid var(--br,#e2e8f0);border-radius:7px;font-size:14px;color:var(--tx,#1e293b);background:var(--cd2,#f8fafc)">
<div style="display:flex;gap:8px;justify-content:flex-end">
<button onclick="document.getElementById('mh3-alt-lanc').remove()" style="padding:9px 14px;border:1px solid var(--br,#e2e8f0);background:var(--cd2,#f8fafc);color:var(--tx,#1e293b);border-radius:7px;cursor:pointer;font-weight:600">Cancelar</button>
<button onclick="_salvarAlterarLanc()" style="padding:9px 16px;border:none;background:var(--red,#C8102E);color:#fff;border-radius:7px;cursor:pointer;font-weight:700">Salvar</button>
</div>
</div>`;
document.body.appendChild(ov);
setTimeout(function(){ var el=document.getElementById('alt-lanc-just'); if(el) el.focus(); },60);
}
async function _salvarAlterarLanc(){
var ctx=window._altLancCtx; if(!ctx) return;
var justEl=document.getElementById('alt-lanc-just');
var just=((justEl&&justEl.value)||'').trim();
if(!just){ if(typeof toast==='function') toast('Escreva a justificativa.','er'); if(justEl) justEl.focus(); return; }
var senhaEl=document.getElementById('alt-lanc-senha');
var senha=(senhaEl&&senhaEl.value)||'';
if(!senha){ if(typeof toast==='function') toast('Digite a sua senha.','er'); if(senhaEl) senhaEl.focus(); return; }
var novoValor=parseFloat((document.getElementById('alt-lanc-valor')||{}).value||0)||0;
var novoVc=(document.getElementById('alt-lanc-vc')||{}).value||'';
var r=_achaLanc(ctx.id, ctx.ctx);
if(!r){ if(typeof toast==='function') toast('Lançamento não encontrado','er'); return; }
var valAntigo=parseFloat(r.obj[r.vf]||0)||0;
var vcAntigo=r.obj.vc||'';
var resumo='Confirma a alteração?\n\nValor: '+fmt(valAntigo)+'  ->  '+fmt(novoValor)+'\nVencimento: '+(vcAntigo||'(sem)')+'  ->  '+(novoVc||'(sem)')+'\n\nJustificativa: '+just;
if(!confirm(resumo)) return;
var ok=await _validarSenhaSolicitante(senha);
if(!ok){ if(typeof toast==='function') toast('❌ Senha incorreta. Alteração cancelada.','er'); if(senhaEl){senhaEl.value='';senhaEl.focus();} return; }
r.obj[r.vf]=novoValor;
r.obj.vc=novoVc;
var modAud=(ctx.ctx==='med'||ctx.ctx==='venda')?'contas_receber':'contas_pagar';
var quem=(authUser&&authUser.nome)||'?';
var desc='Alterou "'+r.nome+'": valor '+fmt(valAntigo)+'->'+fmt(novoValor)+', venc '+(vcAntigo||'-')+'->'+(novoVc||'-')+'. Por: '+quem+'. Motivo: '+just;
if(typeof auditar==='function') auditar('ALTERACAO', modAud, desc);
if(typeof sv==='function') sv();
var ov=document.getElementById('mh3-alt-lanc'); if(ov) ov.remove();
try{ if(typeof rp==='function') rp(cur); }catch(e){}
if(typeof toast==='function') toast('Lançamento alterado e registrado no histórico.','ok');
}
function excluirLanc(id, ctx){
if(typeof ehAdminAtual==='function' && !ehAdminAtual()){ if(typeof toast==='function') toast('Apenas o administrador pode excluir lançamentos.','er'); return; }
var r=_achaLanc(id, ctx);
if(!r){ if(typeof toast==='function') toast('Lançamento não encontrado','er'); return; }
var valor=parseFloat(r.obj[r.vf]||0)||0;
if(!confirm('EXCLUIR este lançamento?\n\n'+r.nome+' - '+fmt(valor)+'\n\nEsta ação não pode ser desfeita.\n(Vou pedir sua senha em seguida.)')) return;
reqSenha(function(){
var idx=r.arr.findIndex(function(x){ return x.id===id; });
if(idx>-1) r.arr.splice(idx,1);
var modAud=(ctx==='med'||ctx==='venda')?'contas_receber':'contas_pagar';
if(typeof auditar==='function') auditar('EXCLUSAO', modAud, 'Excluiu lançamento: '+r.nome+' ('+fmt(valor)+')');
if(typeof sv==='function') sv();
try{ if(typeof rp==='function') rp(cur); }catch(e){}
if(typeof toast==='function') toast('Lançamento excluído.','ok');
});
}
function rdContasPagar(){
const tb=document.getElementById('cp2-tb');
if(!tb) return;
const bar=document.getElementById('fv-cp-bar'); if(bar&&!bar.innerHTML)bar.innerHTML=filtroVencBar('cp');
const selF=document.getElementById('fv-cp'); if(selF)selF.value=_filtroVenc.cp;
const selSp=document.getElementById('st-cp'); if(selSp)selSp.value=(window._statusLanc&&window._statusLanc.cp)||'aberto';
const itemsBase=[...D.nfs.filter(n=>n.cp==='sim').map(n=>({...n,tipo:'NF',desc:n.desc||'NF '+n.num,forn:n.forn})),
...D.despesas.map(d=>({...d,tipo:'Despesa',desc:d.desc,forn:d.forn}))];
const items=aplicarFiltroStatus(aplicarFiltroVenc(itemsBase,'cp','vc'),'cp');
const totalPend=items.filter(c=>c.st!=='pago').reduce((s,c)=>s+(parseFloat(c.vl)||0),0);
tb.innerHTML=items.length?items.map(c=>`<tr>
<td style="font-size:11px"><b>${c.desc||'-'}</b>${badgeAntigo(c)}</td>
<td>${c.antigo?'<span class="badge" style="background:rgba(120,120,120,.18);color:#888;font-weight:800">Antigo</span>':'<span class="badge b-gr">'+c.tipo+'</span>'}</td>
<td style="font-size:10px">${c.forn||'-'}</td>
<td>${fmtDataUrg(c.vc, c.st==='pago')}</td>
<td style="color:var(--or);font-weight:600">${fmt(c.vl)}</td>
<td>${c.st==='pago'?'<span class="badge b-gn">✅ Pago</span>':'<span class="badge b-yw">⏳ Pendente</span>'}${c.travada?' 🔒':''}</td>
<td style="white-space:nowrap"><button class="btn bcy btn-xs" onclick="verContaLanc('${c.id}','${c.tipo}')" title="Ver detalhes">🔍</button> ${podeEnviarEmail()?`<button class="btn btn-xs" style="background:var(--cy);color:#fff" onclick="enviarEmailCP('${c.id}','${c.tipo}')" title="Enviar por e-mail">📧</button> `:''}${c.st!=='pago'?`<button class="btn bg btn-xs" onclick="baixarCp('${c.id}','${c.tipo}')" title="Marcar como pago">✓ Baixar</button>`:'<span style="font-size:9px;color:var(--mt)">Quitado</span>'} <button class="btn bw btn-xs" onclick="abrirAlterarLanc('${c.id}','${c.tipo}')" title="Alterar (com justificativa e senha)">✏️</button> <button class="btn bd btn-xs" onclick="excluirLanc('${c.id}','${c.tipo}')" title="Excluir (somente administrador)">🗑</button></td>
</tr>`).join(''):'<tr><td colspan="7" class="empty">Nenhuma conta a pagar</td></tr>';
const el=document.getElementById('cp2-total'); if(el) el.textContent=fmt(totalPend);
}
function rdContasReceber(){
const tb=document.getElementById('cr2-tb');
if(!tb) return;
const bar=document.getElementById('fv-cr-bar'); if(bar&&!bar.innerHTML)bar.innerHTML=filtroVencBar('cr');
const selF=document.getElementById('fv-cr'); if(selF)selF.value=_filtroVenc.cr;
const itemsBase=[...D.medicoes.map(m=>({...m,origem:'Medição',cli:m.cl,tipo:'med'})),
...D.vendas.filter(v=>v.faturada!==false&&!_vendaVinculada(v.id)).map(v=>({...v,origem:'Venda',cli:v.cli,total:v.total,tipo:'venda'}))]
;
const selSr=document.getElementById('st-cr'); if(selSr)selSr.value=(window._statusLanc&&window._statusLanc.cr)||'aberto';
const items=aplicarFiltroStatus(aplicarFiltroVenc(itemsBase,'cr','vc'),'cr');
const total=items.filter(x=>x.st!=='paga'&&x.st!=='pago').reduce((s,x)=>s+(x.total||0),0);
tb.innerHTML=items.length?items.map(x=>`<tr>
<td><b>${x.cli||'-'}</b>${badgeAntigo(x)}</td>
<td>${x.antigo?'<span class="badge" style="background:rgba(120,120,120,.18);color:#888;font-weight:800">Antigo</span>':'<span class="badge b-bl">'+x.origem+(x.numMed?' Nº'+String(x.numMed).padStart(3,'0'):'')+'</span>'}</td>
<td style="color:var(--gn);font-weight:600">${fmt(x.total)}</td>
<td style="font-size:10px;${x.vc&&dTo(x.vc)<0?'color:var(--red);font-weight:700':''}">${fmtDataUrg(x.vc, x.st==='recebido'||x.st==='pago')}</td>
<td style="font-size:10px">${x.placa||'-'}</td>
<td>
<select style="font-size:11px;padding:3px 5px;border-radius:5px;border:1px solid var(--br);background:var(--cd2);color:var(--tx)" onchange="setStCR('${x.id}','${x.tipo}',this.value,this)">
<option value="pendente" ${!x.st||x.st==='pendente'||x.st==='enviada'||x.st==='aprovada'?'selected':''}>⏳ Pendente</option>
<option value="pago">✅ Pago</option>
<option value="atrasado" ${x.st==='atrasado'?'selected':''}>🔴 Atrasado</option>
<option value="remarcado" ${x.st==='remarcado'?'selected':''}>📅 Remarcado</option>
</select>
<button class="btn btn-xs" style="background:#25D366;color:#fff;border:none;margin-top:5px" onclick="whatsCobranca('${x.id}','${x.tipo}')" title="Enviar WhatsApp">📲</button> <button class="btn bcy btn-xs" onclick="verContaLanc('${x.id}','${x.tipo}')" title="Ver detalhes" style="margin-top:5px">🔍 Ver</button>${podeEnviarEmail()?`<button class="btn btn-xs" style="background:var(--cy);color:#fff;margin-top:5px;margin-left:4px" onclick="enviarEmailCR('${x.id}','${x.tipo}')" title="Enviar cobrança por e-mail">📧</button>`:''} <button class="btn bw btn-xs" style="margin-top:5px;margin-left:4px" onclick="abrirAlterarLanc('${x.id}','${x.tipo}')" title="Alterar (com justificativa e senha)">✏️</button> <button class="btn bd btn-xs" style="margin-top:5px;margin-left:4px" onclick="excluirLanc('${x.id}','${x.tipo}')" title="Excluir (somente administrador)">🗑</button>
</td>
</tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma conta a receber</td></tr>';
const el=document.getElementById('cr2-total'); if(el) el.textContent=fmt(total);
}
function setStCR(id, tipo, novoSt, sel){
const lista=tipo==='med'?D.medicoes:D.vendas;
const x=lista.find(i=>i.id===id);
if(!x){toast('Registro não encontrado','er');return;}
if(novoSt==='remarcado'){
const nd=prompt('Nova data de vencimento (AAAA-MM-DD):', x.vc||'');
if(!nd){sel.value=x.st||'pendente';return;}
x.vc=nd; // ALTERA A INFORMAÇÃO PARA A NOVA DATA
x.st='remarcado';
x.fluxo='sim';
if(typeof auditarExclusao==='function')auditarExclusao(tipo==='med'?'medicoes':'vendas','REMARCADO para '+nd+': '+(x.cli||x.cl||'')+' '+fmt(x.total||0));
toast('📅 Remarcado! Nova data: '+nd,'ok');
} else if(novoSt==='atrasado'){
x.st='atrasado';x.prejuizo=true;x.fluxo='nao';
if(typeof auditarExclusao==='function')auditarExclusao(tipo==='med'?'medicoes':'vendas','marcado ATRASADO: '+(x.cli||x.cl||'')+' '+fmt(x.total||0));
toast('🔴 Marcado como Atrasado — vai para Prejuízos','er');
} else if(novoSt==='pago'){
const okb=abrirSelBanco('receber', id, tipo, parseFloat(x.total||0)||0, (x.cli||x.cl||'Recebimento'));
if(!okb){ sel.value=x.st||'pendente'; }
return;
} else {
x.st=novoSt;
}
sv();rdContasReceber();
if(typeof rdFluxo==='function')rdFluxo();
}
let funcFotos=[], funcArqs=[];
function rdFunc(){
const tb=document.getElementById('func-tb');
if(!tb) return;
const fs=D.funcionarios||[];
tb.innerHTML=fs.length?fs.map(f=>`<tr>
<td><b>${f.nome}</b></td>
<td style="font-size:11px">${f.cpf||'-'}</td>
<td style="font-size:11px">${f.cnh||'-'}${f.cnhVal&&dTo(f.cnhVal)<0?' ⚠️':''}</td>
<td style="font-size:11px">${f.tel||'-'}</td>
<td>${f.salario?fmt(f.salario):'-'}</td>
<td style="display:flex;gap:4px">
<button class="btn bg btn-xs" onclick="editFunc('${f.id}')" title="Editar">✏️</button>
<button class="btn bd btn-xs" onclick="delFunc('${f.id}')" title="Excluir">×</button>
</td>
</tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhum funcionário cadastrado</td></tr>';
}
function openFunc(){
document.getElementById('func-eid').value='';
['func-nome','func-cpf','func-rg','func-cnh','func-cnh-val','func-end','func-tel','func-nasc','func-emerg-nome','func-emerg-tel','func-obs','func-ctps','func-pis','func-cargo','func-admissao','func-salario','func-beneficio','func-seg-valor','func-seg-vig','func-seg-seguradora'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
funcFotos=[];funcArqs=[];
renderFuncFotos();renderFuncArqs();
document.querySelector('#m-func .mt2').textContent='👷 Novo Funcionário';
openM('m-func');
}
function saveFunc(){
const nome=document.getElementById('func-nome').value.trim();
const cpf=document.getElementById('func-cpf').value.trim();
if(!nome){toast('Informe o nome','er');return;}
if(!cpf){toast('Informe o CPF','er');return;}
const eid=document.getElementById('func-eid').value;
const data={
nome,cpf,rg:document.getElementById('func-rg').value,
cnh:document.getElementById('func-cnh').value,cnhVal:document.getElementById('func-cnh-val').value,
end:document.getElementById('func-end').value,tel:document.getElementById('func-tel').value,
nasc:document.getElementById('func-nasc').value,
emergNome:document.getElementById('func-emerg-nome').value,emergTel:document.getElementById('func-emerg-tel').value,
obs:document.getElementById('func-obs').value,
ctps:document.getElementById('func-ctps').value,pis:document.getElementById('func-pis').value,
cargo:document.getElementById('func-cargo').value,admissao:document.getElementById('func-admissao').value,
salario:document.getElementById('func-salario').value,beneficio:document.getElementById('func-beneficio').value,
segValor:document.getElementById('func-seg-valor').value,segVig:document.getElementById('func-seg-vig').value,
segSeguradora:document.getElementById('func-seg-seguradora').value,
fotos:[...funcFotos],arqs:[...funcArqs]
};
if(eid){const idx=D.funcionarios.findIndex(f=>f.id===eid);if(idx>-1)D.funcionarios[idx]={...D.funcionarios[idx],...data};toast('Funcionário atualizado!','ok');}
else{data.id=uid();D.funcionarios.push(data);toast('Funcionário cadastrado!','ok');}
sv();closeM('m-func');rdFunc();
}
function editFunc(id){if(_bloqEditar('func'))return;
const f=D.funcionarios.find(x=>x.id===id);
if(!f) return;
openFunc();
document.getElementById('func-eid').value=id;
const set=(i,v)=>{const el=document.getElementById(i);if(el)el.value=v||'';};
set('func-nome',f.nome);set('func-cpf',f.cpf);set('func-rg',f.rg);set('func-cnh',f.cnh);
set('func-cnh-val',f.cnhVal);set('func-end',f.end);set('func-tel',f.tel);set('func-nasc',f.nasc);
set('func-emerg-nome',f.emergNome);set('func-emerg-tel',f.emergTel);set('func-obs',f.obs);
set('func-ctps',f.ctps);set('func-pis',f.pis);set('func-cargo',f.cargo);set('func-admissao',f.admissao);
set('func-salario',f.salario);set('func-beneficio',f.beneficio);set('func-seg-valor',f.segValor);
set('func-seg-vig',f.segVig);set('func-seg-seguradora',f.segSeguradora);
funcFotos=f.fotos?[...f.fotos]:[];funcArqs=f.arqs?[...f.arqs]:[];
renderFuncFotos();renderFuncArqs();
document.querySelector('#m-func .mt2').textContent='👷 Editar: '+f.nome;
}
function delFunc(id){
reqSenha(()=>{
if(!confirm('Excluir este funcionário?'))return;
var _f=(D.funcionarios||[]).find(f=>f.id===id);
D.funcionarios=D.funcionarios.filter(f=>f.id!==id);
if(typeof auditarExclusao==='function')auditarExclusao('funcionarios','Excluiu funcionário: '+((_f&&(_f.nome||_f.nm))||id));
sv();rdFunc();toast('Funcionário excluído','ok');
});
}
function addFuncFoto(inp){
Array.from(inp.files).forEach(file=>{
const r=new FileReader();
r.onload=e=>{funcFotos.push(e.target.result);renderFuncFotos();};
r.readAsDataURL(file);
});
}
function renderFuncFotos(){
const grid=document.getElementById('func-foto-grid');
if(!grid)return;
const add=grid.querySelector('label');
grid.querySelectorAll('img').forEach(i=>i.remove());
funcFotos.forEach((src,i)=>{
const img=document.createElement('img');img.src=src;
img.style.cssText='width:60px;height:60px;object-fit:cover;border-radius:4px;cursor:pointer';
img.onclick=()=>{if(confirm('Remover foto?')){funcFotos.splice(i,1);renderFuncFotos();}};
grid.insertBefore(img,add);
});
}
function addFuncArq(inp){
Array.from(inp.files).forEach(file=>{
const r=new FileReader();
r.onload=e=>{funcArqs.push({nome:file.name,data:e.target.result});renderFuncArqs();};
r.readAsDataURL(file);
});
}
function renderFuncArqs(){
const el=document.getElementById('func-arq-list');
if(!el)return;
el.innerHTML=funcArqs.map((a,i)=>`<div style="display:flex;justify-content:space-between;padding:6px;background:var(--cd2);border-radius:5px;margin-bottom:4px;font-size:12px"><span>📄 ${a.nome}</span><button class="btn bd btn-xs" onclick="funcArqs.splice(${i},1);renderFuncArqs()">×</button></div>`).join('');
}
function rdClientes(){
const tb=document.getElementById('cli-tb');
if(!tb) return;
const cs=D.clientes||[];
tb.innerHTML=cs.length?cs.map(c=>{
const nCts=D.contratos.filter(ct=>ct.clienteId===c.id).length;
return `<tr>
<td><b>${c.nome}</b></td>
<td style="font-size:11px">${c.cnpj||'-'}</td>
<td style="font-size:11px">${c.obra||'-'}</td>
<td><span class="badge b-bl">${nCts}</span></td>
<td style="display:flex;gap:4px">
<button class="btn bg btn-xs" onclick="editCliente('${c.id}')" title="Editar">✏️</button>
<button class="btn bd btn-xs" onclick="delCliente('${c.id}')" title="Excluir">×</button>
</td>
</tr>`;
}).join(''):'<tr><td colspan="5" class="empty">Nenhum cliente cadastrado. Cadastre primeiro o cliente, depois o contrato.</td></tr>';
}
function openCliente(){
document.getElementById('cli-eid').value='';
['cli-nome','cli-cnpj','cli-obra','cli-cidade','cli-tel','cli-email','cli-obs'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
openM('m-cliente');
}
function saveCliente(){
const nome=document.getElementById('cli-nome').value.trim();
const cnpj=document.getElementById('cli-cnpj').value.trim();
if(!nome){toast('Informe o nome do cliente','er');return;}
if(!cnpj){toast('Informe o CNPJ','er');return;}
const eid=document.getElementById('cli-eid').value;
const data={
nome,cnpj,
obra:document.getElementById('cli-obra').value,
cidade:document.getElementById('cli-cidade').value,
tel:document.getElementById('cli-tel').value,
email:document.getElementById('cli-email').value.trim(),
obs:document.getElementById('cli-obs').value
};
if(eid){const i=D.clientes.findIndex(c=>c.id===eid);if(i>-1)D.clientes[i]={...D.clientes[i],...data};toast('Cliente atualizado!','ok');}
else{data.id=uid();D.clientes.push(data);toast('Cliente cadastrado!','ok');}
auditar(eid?'ALTERACAO':'CRIACAO','clientes',(eid?'Cliente alterado':'Cliente criado')+': '+nome);sv();closeM('m-cliente');rdClientes();
}
function editCliente(id){if(_bloqEditar('clientes'))return;
const c=D.clientes.find(x=>x.id===id);
if(!c)return;
openCliente();
document.getElementById('cli-eid').value=id;
document.getElementById('cli-nome').value=c.nome||'';
document.getElementById('cli-cnpj').value=c.cnpj||'';
document.getElementById('cli-obra').value=c.obra||'';
document.getElementById('cli-cidade').value=c.cidade||'';
document.getElementById('cli-tel').value=c.tel||'';
document.getElementById('cli-email').value=c.email||'';
document.getElementById('cli-obs').value=c.obs||'';
}
function delCliente(id){
const usuarioLogado=(authUser&&authUser.nome?authUser.nome:'').toLowerCase();
const loginLogado=(authUser&&authUser.login?authUser.login:'').toLowerCase();
if(!usuarioLogado.includes('noninho')&&!loginLogado.includes('noninho')){
toast('🚫 Somente o Noninho pode excluir clientes.','er');
if(typeof auditarExclusao==='function')auditarExclusao('clientes','TENTATIVA de exclusão de cliente NEGADA para: '+(authUser?authUser.nome:'?'));
return;
}
const temCt=D.contratos.some(ct=>ct.clienteId===id);
if(temCt){toast('Cliente tem contratos vinculados. Exclua os contratos primeiro.','er');return;}
reqSenha(()=>{
if(!confirm('Excluir este cliente?'))return;
const cli=D.clientes.find(c=>c.id===id);
if(typeof auditarExclusao==='function')auditarExclusao('clientes','Cliente EXCLUÍDO: '+(cli?cli.nome:id));
D.clientes=D.clientes.filter(c=>c.id!==id);
sv();rdClientes();toast('Cliente excluído','ok');
});
}
function popContratosMob(){
const sel=document.getElementById('mob-contrato');
if(!sel) return;
sel.innerHTML='<option value="">Selecionar contrato...</option><option value="__avulso__">🚛 Avulso — sem contrato / veículo não cadastrado</option>';
D.contratos.filter(c=>c.status!=='encerrado').forEach(c=>{
sel.innerHTML+=`<option value="${c.id}">${c.placa||'?'} — ${c.cl} ${c.ob?'('+c.ob+')':''}</option>`;
});
}
function puxarDadosContratoMob(){
const ctId=document.getElementById('mob-contrato').value;
var pl=document.getElementById('mob-placa'),cli=document.getElementById('mob-cliente'),loc=document.getElementById('mob-local');
if(ctId==='__avulso__'){
[pl,cli,loc].forEach(function(el){if(el){el.readOnly=false;el.style.background='';el.value='';}});
if(pl)pl.placeholder='Digite a placa';if(cli)cli.placeholder='Digite o cliente';if(loc)loc.placeholder='Digite a cidade';
return;
}
[pl,cli,loc].forEach(function(el){if(el){el.readOnly=true;el.style.background='var(--cd2)';}});
const ct=D.contratos.find(c=>c.id===ctId);
if(!ct){
if(pl)pl.value='';if(cli)cli.value='';if(loc)loc.value='';
return;
}
document.getElementById('mob-placa').value=ct.placa||'';
document.getElementById('mob-cliente').value=ct.cl||'';
const cliCad=(D.clientes||[]).find(c=>c.id===ct.clienteId);
document.getElementById('mob-local').value=cliCad?(cliCad.cidade||''):'';
toast('Dados puxados do contrato!','ok');
}
function popChecklistsMob(){
const sel=document.getElementById('mob-checklist');
if(!sel) return;
sel.innerHTML='<option value="">➕ Adicionar checklist...</option>';
(D.checklists||[]).forEach(function(c){
sel.innerHTML+='<option value="'+c.id+'">'+(c.nm||c.nome||c.titulo||'Checklist')+'</option>';
});
}
function carregarChecklistMob(){
const sel=document.getElementById('mob-checklist');
if(!sel) return;
const clId=sel.value;
if(!clId){return;}
const cl=(D.checklists||[]).find(function(c){return c.id===clId;});
if(!cl){return;}
var nome=cl.nm||cl.nome||cl.titulo||'Checklist';
if(mobClIs.some(function(i){return (i.grupo||'')===nome;})){ toast('Este checklist já foi adicionado.','er'); sel.value=''; return; }
var itens=cl.items||cl.itens||cl.its||[];
itens.forEach(function(item){
var txt=(typeof item==='string')?item:(item.txt||item.texto||item.nome||'Item');
mobClIs.push({id:uid(),txt:txt,ck:false,grupo:nome});
});
sel.value='';
rdMobCl();
toast('Checklist "'+nome+'" adicionado.','ok');
}
function togMobCl(id){var i=mobClIs.find(function(x){return x.id===id;});if(i){i.ck=!i.ck;rdMobCl();}}
function rmGrupoMobCl(grupo){mobClIs=mobClIs.filter(function(i){return (i.grupo||'Itens')!==grupo;});rdMobCl();}
function rdMobCl(){
var escH=function(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
var box=document.getElementById('mob-cl-items'); if(!box) return;
if(!mobClIs.length){box.innerHTML='';return;}
var ck=mobClIs.filter(function(i){return i.ck;}).length;
var grupos={}, ordem=[];
mobClIs.forEach(function(i){var g=i.grupo||'Itens';if(!grupos[g]){grupos[g]=[];ordem.push(g);}grupos[g].push(i);});
var html='<div style="font-size:9px;color:var(--mt);margin-bottom:6px">'+ck+'/'+mobClIs.length+' marcados · '+ordem.length+' checklist(s)</div>';
ordem.forEach(function(g){
html+='<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center;background:var(--cd);border:1px solid var(--br);border-radius:5px 5px 0 0;padding:4px 8px"><span style="font-size:10px;font-weight:700;color:var(--cy)">📋 '+escH(g)+'</span><button class="btn bd btn-xs" data-g="'+escH(g)+'" onclick="rmGrupoMobCl(this.dataset.g)" title="Remover este checklist">×</button></div>';
html+=grupos[g].map(function(i){return '<label style="display:flex;align-items:center;gap:8px;padding:6px;background:var(--cd2);border:1px solid var(--br);border-top:none;font-size:12px;cursor:pointer"><input type="checkbox" '+(i.ck?'checked':'')+' onclick="togMobCl(\''+i.id+'\')"> <span style="'+(i.ck?'text-decoration:line-through;color:var(--mt)':'')+'">'+escH(i.txt)+'</span></label>';}).join('');
html+='</div>';
});
box.innerHTML=html;
}
function imprimirMob(id, comFotos, detalhada){
if(detalhada===undefined)detalhada=true;
const m=D.mobilizacoes.find(x=>x.id===id);
if(!m){toast('Mobilização não encontrada','er');return;}
const stLbl={aguardando:'⏳ Aguardando',vigente:'🟢 Vigente',finalizado:'✅ Finalizado'};
const tipoLbl=m.tipo==='desmobilizacao'?'DESMOBILIZAÇÃO':'MOBILIZAÇÃO';
let htmlImp=`<html><head><title>${tipoLbl} ${m.placa}</title>
<style>@page{margin:15mm}@media print{body{padding:0!important}}body{font-family:Arial;padding:20px}h1{font-size:18px}h3{font-size:14px;margin-top:16px}table{width:100%;border-collapse:collapse;margin:10px 0}td,th{border:1px solid #ccc;padding:6px;font-size:12px;text-align:left}img{max-width:200px;margin:5px;border-radius:4px}.vazio{color:#999}</style>
</head><body>
<h1>MH3 RENTAL — ${tipoLbl}</h1>
<table>
<tr><th>Tipo</th><td>${tipoLbl}</td><th>Status</th><td>${stLbl[m.status]||m.status||'-'}</td></tr>
<tr><th>Placa</th><td>${m.placa||'-'}</td><th>Cliente</th><td>${m.cliente||'-'}</td></tr>
<tr><th>Cidade</th><td>${m.local||'-'}</td><th>Saída</th><td>${fmtData(m.saida)}</td></tr>
${m.tipo==='desmobilizacao'||m.chegada?`<tr><th>Chegada/Retorno</th><td colspan="3">${fmtData(m.chegada)}</td></tr>`:''}
</table>`;
if(detalhada){
const px=m.pneus||{};
const nomes={p1:'1º Eixo',p2:'2º Eixo',p3:'3º Eixo',p4:'4º Eixo',pe:'🛞 Estepe'};
htmlImp+='<h3>Pneus por Eixo (completo)</h3><table><tr><th>Eixo</th><th>Marca</th><th>Nº MH3</th><th>Medida</th><th>Reformado</th></tr>';
['p1','p2','p3','p4','pe'].forEach(p=>{
const d=px[p]||{};
const tem=d.mk||d.num||d.med;
htmlImp+=`<tr${tem?'':' class="vazio"'}><td>${nomes[p]}</td><td>${d.mk||'—'}</td><td>${d.num||'—'}</td><td>${d.med||'—'}</td><td>${d.ref==='sim'?'Sim':'Não'}</td></tr>`;
});
htmlImp+='</table>';
htmlImp+=`<h3>Observações</h3><p>${m.obs||'<span class="vazio">— sem observações —</span>'}</p>`;
}
if(detalhada&&comFotos&&m.fotos&&m.fotos.length){
htmlImp+='<h3>Fotos ('+m.fotos.length+')</h3>';
m.fotos.forEach(f=>{htmlImp+=`<img src="${f}">`;});
}
htmlImp+=`<p style="margin-top:20px;font-size:10px;color:#666">Impresso em ${new Date().toLocaleDateString('pt-BR')} ${new Date().toLocaleTimeString('pt-BR')} — Modo: ${detalhada?'DETALHADO':'SIMPLIFICADO'}</p>`;
htmlImp+='</body></html>';
const w=window.open('','_blank');
w.document.write(htmlImp);
w.document.close();
setTimeout(()=>w.print(),500);
}
function perguntarImprimirMob(id){
const m=D.mobilizacoes.find(x=>x.id===id);
const detalhada=confirm('📄 TIPO DE IMPRESSÃO\n\nOK = DETALHADA (pneus, checklist, observações)\nCancelar = SIMPLIFICADA (dados básicos)');
let comFotos=false;
if(detalhada&&m&&m.fotos&&m.fotos.length>0){
comFotos=confirm('Incluir as fotos?\n\nOK = Com fotos\nCancelar = Sem fotos');
}
auditar('IMPRESSAO','mobilizacao',(detalhada?'Detalhada':'Simplificada')+(comFotos?' com fotos':'')+': '+(m?m.placa:id));
imprimirMob(id, comFotos, detalhada);
}
function rdMob(){
const el=document.getElementById('mob-lista');
if(!el) return;
const mobs=[...(D.mobilizacoes||[])].reverse();
if(!mobs.length){
el.innerHTML='<div class="empty"><div class="ei">📸</div>Nenhuma mobilização registrada. Clique em "+ Nova" para começar.</div>';
return;
}
const stLbl={aguardando:'⏳ Aguardando',vigente:'🟢 Vigente',finalizado:'✅ Finalizado'};
const stBadge={aguardando:'b-yw',vigente:'b-gn',finalizado:'b-gr'};
el.innerHTML=`<div class="tw"><table>
<thead><tr><th>Tipo</th><th>Placa</th><th>Cliente/Obra</th><th>Saída</th><th>Chegada</th><th>Status</th><th>Ações</th></tr></thead>
<tbody>${mobs.map(m=>`<tr>
<td><span class="badge ${m.tipo==='desmobilizacao'?'b-pu':'b-bl'}">${m.tipo==='desmobilizacao'?'📥 Desmob.':'📤 Mob.'}</span></td>
<td><b>${m.placa}</b></td>
<td style="font-size:11px">${m.cliente||'-'}</td>
<td style="font-size:11px">${fmtData(m.saida)}</td>
<td style="font-size:11px">${fmtData(m.chegada)}</td>
<td><span class="badge ${stBadge[m.status]||'b-gr'}">${stLbl[m.status]||m.status}</span></td>
<td style="display:flex;gap:4px">
<button class="btn bb btn-xs" onclick="perguntarImprimirMob('${m.id}')" title="Imprimir (com ou sem fotos)">🖨</button>
<button class="btn bg btn-xs" onclick="editMob('${m.id}')" title="Editar">✏️</button>
<button class="btn bd btn-xs" onclick="delMob('${m.id}')" title="Excluir">×</button>
</td>
</tr>`).join('')}</tbody></table></div>`;
}
function openMob(){
document.getElementById('mob-eid').value='';
document.getElementById('mob-saida').value=new Date().toISOString().substring(0,10);
document.getElementById('mob-chegada').value='';
document.getElementById('mob-status').value='aguardando';
const tipoEl=document.getElementById('mob-tipo');
if(tipoEl){tipoEl.value='mobilizacao';toggleTipoMob();}
['mob-pe-mk','mob-pe-num','mob-pe-med'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
document.getElementById('mob-cliente').value='';
document.getElementById('mob-local').value='';
document.getElementById('mob-obs').value='';
['mob-p1-mk','mob-p1-num','mob-p1-med','mob-p2-mk','mob-p2-num','mob-p2-med','mob-p3-mk','mob-p3-num','mob-p3-med','mob-p4-mk','mob-p4-num','mob-p4-med'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
mobModalFotos=[];if(typeof renderMobModalFotos==='function')renderMobModalFotos();
popContratosMob();
popChecklistsMob();
document.getElementById('mob-contrato').value='';
document.getElementById('mob-cliente').value='';
document.getElementById('mob-local').value='';
mobClIs=[]; if(typeof rdMobCl==='function')rdMobCl();
document.querySelector('#m-mob .mt2').textContent='📸 Nova Mobilização';
openM('m-mob');
}
function toggleTipoMob(){
const tipo=document.getElementById('mob-tipo').value;
const saidaBox=document.getElementById('mob-saida-box');
const chegadaBox=document.getElementById('mob-chegada-box');
if(tipo==='mobilizacao'){
if(saidaBox)saidaBox.style.display='';
if(chegadaBox){chegadaBox.style.display='none';document.getElementById('mob-chegada').value='';}
}else{
if(saidaBox)saidaBox.style.display='';
if(chegadaBox)chegadaBox.style.display='';
}
}
function sugereStatusMob(){
const tipo=document.getElementById('mob-tipo')?document.getElementById('mob-tipo').value:'mobilizacao';
const saida=document.getElementById('mob-saida').value;
const chegada=document.getElementById('mob-chegada').value;
const stSel=document.getElementById('mob-status');
const hoje=new Date().toISOString().substring(0,10);
if(tipo==='desmobilizacao' && chegada && chegada<=hoje){
stSel.value='finalizado';
} else if(saida && saida<=hoje){
stSel.value='vigente';
} else {
stSel.value='aguardando';
}
}
function gv(id){const el=document.getElementById(id);return el?el.value:'';}
let mobModalFotos=[];
function addMobModalFoto(inp){
Array.from(inp.files).forEach(file=>{
_comprimirImg(file, 1600, 0.72, function(src, nm){
if(!src) return;
mobModalFotos.push(src); renderMobModalFotos();
_uploadFoto(src, nm, function(u){
if(u && u!==src){ var i=mobModalFotos.indexOf(src); if(i>=0){ mobModalFotos[i]=u; renderMobModalFotos(); } }
});
});
});
inp.value='';
}
function renderMobModalFotos(){
const grid=document.getElementById('mob-foto-grid');
if(!grid)return;
const add=grid.querySelector('label');
grid.querySelectorAll('img').forEach(i=>i.remove());
mobModalFotos.forEach((src,i)=>{
const img=document.createElement('img');img.src=src;
img.style.cssText='width:60px;height:60px;object-fit:cover;border-radius:4px;cursor:pointer';
img.onclick=()=>{if(confirm('Remover foto?')){mobModalFotos.splice(i,1);renderMobModalFotos();}};
grid.insertBefore(img,add);
});
}
function saveMob(){
if(typeof _fotosEnviando!=='undefined' && _fotosEnviando>0){ toast('⏳ Aguarde — ainda enviando '+_fotosEnviando+' foto(s) ao servidor. Tente salvar daqui a alguns segundos.','er'); return; }
const ctIdMob=document.getElementById('mob-contrato')?document.getElementById('mob-contrato').value:'';
const placa=document.getElementById('mob-placa').value;
const saida=document.getElementById('mob-saida').value;
var avulso=(ctIdMob==='__avulso__');
if(!ctIdMob){toast('Selecione o contrato (ou Avulso)','er');return;}
if(!placa){toast(avulso?'Informe a placa do veículo':'Contrato sem placa — verifique o contrato','er');return;}
if(!saida){toast('Informe a data de saída','er');return;}
const eid=document.getElementById('mob-eid').value;
const data={
ctId:avulso?'':ctIdMob,
avulso:avulso,
placa,saida,
chegada:document.getElementById('mob-chegada').value,
status:document.getElementById('mob-status').value,
cliente:document.getElementById('mob-cliente').value,
local:document.getElementById('mob-local').value,
obs:document.getElementById('mob-obs').value,
tipo:document.getElementById('mob-tipo')?document.getElementById('mob-tipo').value:'mobilizacao',
pneus:{
p1:{mk:gv('mob-p1-mk'),num:gv('mob-p1-num'),med:gv('mob-p1-med'),ref:gv('mob-p1-ref')},
p2:{mk:gv('mob-p2-mk'),num:gv('mob-p2-num'),med:gv('mob-p2-med'),ref:gv('mob-p2-ref')},
p3:{mk:gv('mob-p3-mk'),num:gv('mob-p3-num'),med:gv('mob-p3-med'),ref:gv('mob-p3-ref')},
p4:{mk:gv('mob-p4-mk'),num:gv('mob-p4-num'),med:gv('mob-p4-med'),ref:gv('mob-p4-ref')},
pe:{mk:gv('mob-pe-mk'),num:gv('mob-pe-num'),med:gv('mob-pe-med'),ref:gv('mob-pe-ref')}
},
fotos:[...mobModalFotos],
checklist:[...mobClIs]
};
if(eid){
const idx=D.mobilizacoes.findIndex(m=>m.id===eid);
if(idx>-1) D.mobilizacoes[idx]={...D.mobilizacoes[idx],...data};
toast('Mobilização atualizada!','ok');
}else{
data.id=uid();
D.mobilizacoes.push(data);
toast('Mobilização criada!','ok');
}
sv();if(window.emailAutoSe)window.emailAutoSe('mobilizacao', eid?D.mobilizacoes.find(function(m){return m.id===eid;}):data);closeM('m-mob');rdMob();
}
function editMob(id){if(_bloqEditar('mob'))return;
const m=D.mobilizacoes.find(x=>x.id===id);
if(!m) return;
openMob();
document.getElementById('mob-eid').value=id;
mobClIs=(m.checklist||[]).slice(); if(typeof rdMobCl==='function')rdMobCl();
const tipoSel=document.getElementById('mob-tipo');
if(tipoSel){tipoSel.value=m.tipo||'mobilizacao';toggleTipoMob();}
const ctSel=document.getElementById('mob-contrato');
if(ctSel&&m.ctId)ctSel.value=m.ctId;
document.getElementById('mob-placa').value=m.placa||'';
document.getElementById('mob-saida').value=m.saida||'';
document.getElementById('mob-chegada').value=m.chegada||'';
document.getElementById('mob-status').value=m.status||'aguardando';
document.getElementById('mob-cliente').value=m.cliente||'';
document.getElementById('mob-local').value=m.local||'';
document.getElementById('mob-obs').value=m.obs||'';
const px=m.pneus||{};
['p1','p2','p3','p4','pe'].forEach(p=>{
const dados=px[p]||{};
const set=(suf,v)=>{const el=document.getElementById('mob-'+p+'-'+suf);if(el)el.value=v||(suf==='ref'?'nao':'');};
set('mk',dados.mk);set('num',dados.num);set('med',dados.med);set('ref',dados.ref);
});
mobModalFotos=m.fotos?[...m.fotos]:[];
if(typeof renderMobModalFotos==='function')renderMobModalFotos();
document.querySelector('#m-mob .mt2').textContent=(m.tipo==='desmobilizacao'?'📥 Editar Desmobilização':'📤 Editar Mobilização');
}
function delMob(id){
reqSenha(()=>{
if(!confirm('Excluir esta mobilização?')) return;
D.mobilizacoes=D.mobilizacoes.filter(m=>m.id!==id);
if(typeof auditarExclusao==='function')auditarExclusao('mobilizacao','Excluiu mobilização: '+id);
sv();rdMob();toast('Mobilização excluída','ok');
});
}
function rdRelCPagar(){
const el=document.getElementById('rel-cpagar-c');
if(!el) return;
const items=[...D.nfs.filter(n=>n.cp==='sim'),...D.despesas].sort((a,b)=>new Date(a.vc||'9999')-new Date(b.vc||'9999'));
const tot=items.reduce((s,c)=>s+(parseFloat(c.vl)||0),0);
const pend=items.filter(c=>c.st!=='pago').reduce((s,c)=>s+(parseFloat(c.vl)||0),0);
el.innerHTML=`<div style="display:flex;gap:10px;margin-bottom:12px">
<div class="kpi"><div style="font-size:10px;color:var(--mt)">TOTAL</div><div style="font-size:18px;font-weight:700">${fmt(tot)}</div></div>
<div class="kpi"><div style="font-size:10px;color:var(--mt)">PENDENTE</div><div style="font-size:18px;font-weight:700;color:var(--or)">${fmt(pend)}</div></div>
</div>
<div class="tw"><table><thead><tr><th>Descrição</th><th>Fornecedor</th><th>Valor</th><th>Venc.</th><th>Status</th></tr></thead>
<tbody>${items.map(c=>`<tr><td>${c.desc||'NF '+(c.num||'')}</td><td>${c.forn||'-'}</td><td style="color:var(--or)">${fmt(c.vl)}</td><td>${fmtData(c.vc)}</td><td>${c.st==='pago'?'✅ Pago':'⏳ Pendente'}</td></tr>`).join('')||'<tr><td colspan=5 class=empty>Vazio</td></tr>'}</tbody></table></div>`;
}
function rdRelCReceber(){
const el=document.getElementById('rel-creceber-c');
if(!el) return;
const items=[...D.medicoes.map(m=>({...m,cli:m.cl,origem:'Medição'})),...D.vendas.map(v=>({...v,cli:v.cli,origem:'Venda'}))];
const tot=items.reduce((s,x)=>s+(x.total||0),0);
const rec=items.filter(x=>x.st==='paga'||x.st==='pago').reduce((s,x)=>s+(x.total||0),0);
el.innerHTML=`<div style="display:flex;gap:10px;margin-bottom:12px">
<div class="kpi"><div style="font-size:10px;color:var(--mt)">TOTAL</div><div style="font-size:18px;font-weight:700">${fmt(tot)}</div></div>
<div class="kpi"><div style="font-size:10px;color:var(--mt)">RECEBIDO</div><div style="font-size:18px;font-weight:700;color:var(--gn)">${fmt(rec)}</div></div>
</div>
<div class="tw"><table><thead><tr><th>Cliente</th><th>Origem</th><th>Valor</th><th>Venc.</th><th>Status</th></tr></thead>
<tbody>${items.map(x=>`<tr><td>${x.cli||'-'}</td><td>${x.origem}</td><td style="color:var(--gn)">${fmt(x.total)}</td><td>${fmtData(x.vc)}</td><td>${x.st==='paga'||x.st==='pago'?'✅ Recebido':'⏳ Pendente'}</td></tr>`).join('')||'<tr><td colspan=5 class=empty>Vazio</td></tr>'}</tbody></table></div>`;
}
function rdRelResPlaca(){
const el=document.getElementById('rel-resplaca-c');
if(!el) return;
el.innerHTML='<p style="color:var(--mt);font-size:13px;padding:12px">Use a aba <b>Relatórios → Resultado por Placa</b> no menu lateral para o relatório completo com filtros.</p><div id="rel-resplaca-tab"></div>';
let rows=[];
D.equips.forEach(eq=>{
const meds=D.medicoes.filter(m=>m.eqId===eq.id&&m.st==='paga');
const rec=meds.reduce((s,m)=>s+(m.total||0),0);
const oss=D.manutencoes.filter(m=>m.eqId===eq.id&&!ehImpressao(m));
const custoOS=oss.reduce((s,m)=>s+((m.lancs||[]).reduce((ss,l)=>ss+l.qtd*l.val,0)),0);
const desps=D.despesas.filter(d=>d.placa===eq.placa);
const custoDesp=desps.reduce((s,d)=>s+(parseFloat(d.vl)||0),0);
rows.push({eq,rec,custoOS,custoDesp,res:rec-custoOS-custoDesp});
});
document.getElementById('rel-resplaca-tab').innerHTML=`<div class="tw"><table>
<thead><tr><th>Placa</th><th>Receitas</th><th>OS</th><th>Despesas</th><th>Resultado</th></tr></thead>
<tbody>${rows.map(r=>`<tr><td><b>${r.eq.placa}</b></td><td style="color:var(--gn)">${fmt(r.rec)}</td><td style="color:var(--red)">${fmt(r.custoOS)}</td><td style="color:var(--red)">${fmt(r.custoDesp)}</td><td style="font-weight:700;color:${r.res>=0?'var(--gn)':'var(--red)'}">${fmt(r.res)}</td></tr>`).join('')}</tbody></table></div>`;
}
function valorDesvalorizado(vaql, dataAql, pct12, pct35){
vaql=parseFloat(vaql)||0;
pct12=parseFloat(pct12)||0;
pct35=parseFloat(pct35)||0;
if(!vaql||!dataAql) return vaql;
const aql=new Date(dataAql+'T12:00');
const hoje=new Date();
let anos=(hoje-aql)/(1000*60*60*24*365.25);
if(anos<0)anos=0;
const pct = anos < 2 ? pct12 : pct35;
const valor = vaql * (1 - Math.min(pct,95)/100);
return Math.max(0, Math.round(valor*100)/100);
}
function periodoDesval(dataAql){
if(!dataAql) return '-';
const anos=(new Date()-new Date(dataAql+'T12:00'))/(1000*60*60*24*365.25);
if(anos<0) return '-';
return anos < 2 ? 'Ano 1-2' : 'Ano 3-5';
}
function calcDesvalEq(){
const vaql=document.getElementById('eq-vaql')?document.getElementById('eq-vaql').value:0;
const daql=document.getElementById('eq-daql')?document.getElementById('eq-daql').value:'';
const t12=document.getElementById('eq-desval12')?document.getElementById('eq-desval12').value:0;
const t35=document.getElementById('eq-desval35')?document.getElementById('eq-desval35').value:0;
const calc=valorDesvalorizado(vaql,daql,t12,t35);
const el=document.getElementById('eq-vl-calc');
if(el)el.value=fmt(calc);
const lbl=document.getElementById('eq-periodo-lbl');
if(lbl)lbl.textContent=daql?'('+periodoDesval(daql)+')':'';
}
