/* ===== vs284 increment 6 (8.2f) — desconto de venda em R$ (em vez de %) ===== */
(function(){
  if(window.__mh3DescVendaReaisV284) return;
  window.__mh3DescVendaReaisV284 = 1;
  function pv(v){ return (typeof _parseValorBR==='function') ? _parseValorBR(v) : (parseFloat(String(v).replace(/\./g,'').replace(',','.'))||0); }
  function subItens(){ try{ return (vdItems||[]).reduce(function(s,i){ return s+(parseFloat(i.qtd)||0)*(parseFloat(i.val)||0); },0); }catch(e){ return 0; } }
  // rotulo "Desconto (%)" -> "Desconto (R$)" e input aceitando virgula
  function ajustaCampo(){
    var inp=document.getElementById('vd-desc'); if(!inp) return false;
    if(inp.type==='number') inp.type='text';
    try{ var lbl=inp.parentNode && inp.parentNode.querySelector('div');
      if(lbl && /Desconto/.test(lbl.textContent) && lbl.textContent.indexOf('R$')<0) lbl.textContent='Desconto (R$)'; }catch(e){}
    return true;
  }
  var t=0; (function tt(){ if(!ajustaCampo() && t++<40) setTimeout(tt,400); })();
  // total ao vivo em R$
  var base=window.rdVdItems;
  if(typeof base==='function'){
    window.rdVdItems=function(){
      var r=base.apply(this,arguments);
      try{ var sub=subItens(), desc=pv((document.getElementById('vd-desc')||{}).value||0);
        var el=document.getElementById('vd-total'); if(el && typeof fmt==='function') el.textContent=fmt(Math.max(0,sub-desc));
      }catch(e){}
      return r;
    };
  }
  // total gravado em R$
  var baseSV=window.saveVenda;
  if(typeof baseSV==='function'){
    window.saveVenda=function(){
      var descR=pv((document.getElementById('vd-desc')||{}).value||0), sub=subItens();
      var antes={}; (D.vendas||[]).forEach(function(v){ if(v&&v.id) antes[v.id]=1; });
      var r=baseSV.apply(this,arguments);
      try{ (D.vendas||[]).forEach(function(v){ if(v&&v.id&&!antes[v.id]){ v.desc=descR; v.descTipo='reais'; v.total=Math.max(0,sub-descR); } });
        if(typeof sv==='function') sv();
      }catch(e){}
      return r;
    };
  }
})();



